        CHECK(Call(host, "net.simulate", R"({"seed":45,"latencyFrames":1,"jitterFrames":1,"lossPermille":50,"duplicatePermille":100,"reorderFrames":1})")["ok"].asBool());
        CHECK(!Call(host, "net.simulate", R"({"latencyFrames":3601})")["ok"].asBool());
