TEST(FbxModelsSkinAndAnimation) {
    Engine e;
    std::string err;
    CHECK(e.Open(TempProject("fbx_loader"), &err));
    Call(e, "scene.new", R"J({"empty":true})J");
    auto fbx = [](const std::string& texture) {
        std::string text = kRigFbx;
        text.replace(text.find("%TEXTURE%"), 9, texture);
        return text;
    };
    auto replace = [](std::string text, const std::string& from, const std::string& to) {
        size_t at = text.find(from);
        CHECK(at != std::string::npos);
        return text.replace(at, from.size(), to);
    };
    const std::string path = JoinPath(e.ProjectDir(), "assets/models/rig.fbx");
    CreateDirectories(ParentPath(path));
    CHECK(WriteTextFile(path, fbx("")));
    CHECK(AssetManager::KindOf("assets/models/Rig.FBX") == "model");
    Json info = Call(e, "asset.info", R"J({"path":"assets/models/rig.fbx"})J")["result"];
    CHECK(info["kind"].asString() == "model" && info["vertices"].asInt() == 4 && info["triangles"].asInt() == 2);
    CHECK(info["joints"].asInt() == 2 && info["clips"].size() == 1 && info["clips"][0]["name"].asString() == "Wave");
    CHECK(info["clips"][0]["duration"].asFloat() == 1 && info["clips"][0]["channels"].asInt() == 1);
    CHECK(Call(e, "asset.list", R"J({"kind":"model"})J")["result"].size() == 1);

    // Centimeters become meters, V flips to the top-left origin, weights follow the clusters.
    Mesh mesh;
    CHECK(LoadModelFile(path, mesh, &err));
    CHECK(Near(mesh.boundsMin, Vec3(0, 0, 0), 1e-5f) && Near(mesh.boundsMax, Vec3(1, 1, 0), 1e-5f));
    CHECK(mesh.positions.size() == 4 && mesh.skin.size() == 4 && mesh.joints.size() == 2 && mesh.submeshes.size() == 1);
    for (size_t i = 0; i < mesh.positions.size(); ++i) {
        const bool top = mesh.positions[i].y > 0.5f;
        CHECK(std::abs(mesh.uvs[i * 2] - mesh.positions[i].x) < 1e-5f && std::abs(mesh.uvs[i * 2 + 1] - (1 - mesh.positions[i].y)) < 1e-5f);
        CHECK(mesh.skin[i].weights[0] == 1 && mesh.skin[i].joints[0] == (top ? 1 : 0));
        CHECK(Near(mesh.normals[i], Vec3(0, 0, 1), 1e-5f));
    }
    const ModelNode& tip = mesh.nodes[static_cast<size_t>(mesh.joints[1].node)];
    CHECK(Near(tip.translation, Vec3(0, 1, 0), 1e-5f) && mesh.joints[0].node == tip.parent);
    CHECK(std::abs(mesh.joints[1].inverseBind.m[13] + 1) < 1e-5f && std::abs(mesh.joints[0].inverseBind.m[13]) < 1e-5f);
    CHECK(mesh.materials.size() == 1 && mesh.materials[0].baseColor == Color(1, 0, 0) && !mesh.materials[0].baseTexture);
    // The curve is resampled into linear keys in seconds and meters.
    CHECK(mesh.clips.size() == 1 && mesh.clips[0].channels.size() == 1);
    const AnimationChannel& channel = mesh.clips[0].channels[0];
    CHECK(channel.node == mesh.joints[1].node && channel.path == AnimationPath::Translation);
    CHECK(channel.interpolation == AnimationInterpolation::Linear && channel.times.size() >= 2 && channel.times.front() == 0);
    CHECK(std::abs(channel.times.back() - 1) < 1e-5f && Near(channel.values.front().xyz(), Vec3(0, 1, 0), 1e-5f));
    CHECK(Near(channel.values.back().xyz(), Vec3(0.5f, 1, 0), 1e-5f));

    // The clip moves the upper edge half a meter along +x in both the pose and the picture.
    Call(e, "entity.create", R"J({"name":"Rig","components":{"MeshRenderer":{"mesh":"assets/models/rig.fbx","unlit":true},
                                 "Animator":{"clip":"Wave","playing":false}}})J");
    EntityId rig = e.GetScene().FindByName("Rig");
    RenderTarget rest = RenderLook(e, Vec3(0.75f, 0.5f, 3), Vec3(0.75f, 0.5f, 0));
    CHECK(Call(e, "component.set", R"J({"id":"Rig","type":"Animator","values":{"time":1}})J")["ok"].asBool());
    RenderTarget moved = RenderLook(e, Vec3(0.75f, 0.5f, 3), Vec3(0.75f, 0.5f, 0));
    auto columns = [&](const RenderTarget& rt, int row) {  // first and last column the quad covers in a row
        std::pair<int, int> range(-1, -1);
        for (int x = 0; x < rt.width; ++x) {
            if (rt.ids[static_cast<size_t>(row * rt.width + x)] != rig) continue;
            if (range.first < 0) range.first = x;
            range.second = x;
        }
        return range;
    };
    CHECK(CountId(rest, rig) > 500 && rest.Hash() != moved.Hash());
    CHECK(columns(rest, 32).first > 0 && columns(moved, 32).first > columns(rest, 32).first + 8);   // upper rows shift right
    CHECK(columns(moved, 32).second > columns(rest, 32).second + 8);
    CHECK(columns(rest, 58).first > 0 && columns(moved, 58).first < columns(rest, 58).first + 4);   // the lower edge stays
    CHECK(WritePng("build/fbx-rig-moved.png", moved.ToImage(), true));

    // Z-up files are turned to Y up.
    std::string zUp = replace(fbx(""), "\"UpAxis\", \"int\", \"Integer\", \"\",1", "\"UpAxis\", \"int\", \"Integer\", \"\",2");
    zUp = replace(zUp, "\"FrontAxis\", \"int\", \"Integer\", \"\",2", "\"FrontAxis\", \"int\", \"Integer\", \"\",1");
    zUp = replace(zUp, "\"FrontAxisSign\", \"int\", \"Integer\", \"\",1", "\"FrontAxisSign\", \"int\", \"Integer\", \"\",-1");
    CHECK(WriteTextFile(path, zUp));
    CHECK(LoadModelFile(path, mesh, &err));
    CHECK(Near(mesh.boundsMin, Vec3(0, 0, -1), 1e-5f) && Near(mesh.boundsMax, Vec3(1, 0, 0), 1e-5f));
    CHECK(Near(mesh.normals[0], Vec3(0, 1, 0), 1e-5f));

    // An image is found by its file name beside the model; the absolute path in the file is never opened.
    Image red;
    red.width = red.height = 1;
    red.rgba = {255, 0, 0, 255};
    CHECK(WritePng(JoinPath(e.ProjectDir(), "assets/models/red.png"), red, true));
    const std::string texture = "\tTexture: 6000, \"Texture::Diffuse\", \"\" {\n\t\tType: \"TextureVideoClip\"\n\t\tVersion: 202\n"
                                "\t\tFileName: \"C:\\art\\tex\\red.png\"\n\t\tRelativeFilename: \"..\\tex\\red.png\"\n\t}\n";
    CHECK(WriteTextFile(path, replace(fbx(texture), "\"A\",1,0,0", "\"A\",0.2,0.2,0.2")));
    CHECK(LoadModelFile(path, mesh, &err));
    CHECK(mesh.textures.size() == 1 && mesh.materials[0].baseTexture == mesh.textures[0] && mesh.materials[0].baseColor == Color(1, 1, 1));
    CHECK(mesh.textures[0]->width == 1 && mesh.textures[0]->texels[0] == 0xFF0000FFu);

    // Broken files report why; a file without triangles but with clips is an animation source (see
    // <model>.clips.json), one with neither is not a model.
    CHECK(WriteTextFile(path, "not an fbx file"));
    CHECK(!LoadModelFile(path, mesh, &err) && err.find("cannot read FBX") != std::string::npos);
    CHECK(WriteTextFile(JoinPath(e.ProjectDir(), "assets/models/broken.fbx"), "not an fbx file"));
    Json bad = Call(e, "asset.info", R"J({"path":"assets/models/broken.fbx"})J");
    CHECK(!bad["ok"].asBool() && bad["error"]["code"].asString() == "invalid_model");
    std::string empty = fbx("");
    empty.erase(empty.find("\tGeometry: 1000"), empty.find("\tModel: 2000") - empty.find("\tGeometry: 1000"));
    CHECK(WriteTextFile(path, empty));
    CHECK(LoadModelFile(path, mesh, &err) && mesh.indices.empty() && !mesh.clips.empty());

    // oe import / asset.import put .fbx files with the other models.
    const std::string outside = JoinPath(e.ProjectDir(), "hero.fbx");
    CHECK(WriteTextFile(outside, fbx("")));
    Json imported = Json::MakeObject();
    imported["source"] = outside;
    CHECK(e.Call("asset.import", imported)["result"]["path"].asString() == "assets/models/hero.fbx");
}

TEST(IkSolverReachesGoals) {
    // Shoulder at the origin, elbow and hand one unit apart along +x, a finger past the hand.
    Mesh mesh;
    auto bone = [&](const char* name, int parent, Vec3 translation) {
        ModelNode node;
        node.name = name;
        node.parent = parent;
        node.translation = translation;
        mesh.nodes.push_back(node);
    };
    bone("Shoulder", -1, Vec3(0, 0, 0));
    bone("Elbow", 0, Vec3(1, 0, 0));
    bone("Hand", 1, Vec3(1, 0, 0));
    bone("Finger", 2, Vec3(0.25f, 0, 0));
    CHECK(FindModelNode(mesh, "Hand") == 2 && FindModelNode(mesh, "Foot") == -1 && FindModelNode(mesh, "") == -1);
    auto position = [](const std::vector<Mat4>& nodes, int node) { return nodes[static_cast<size_t>(node)].TransformPoint(Vec3(0, 0, 0)); };
    auto solve = [&](IkGoal goal) {
        std::vector<Mat4> nodes = EvaluateNodePose(mesh, nullptr, 0);
        goal.node = goal.node < 0 ? 2 : goal.node;
        SolveIk(mesh, nodes, goal);
        // Bones keep their lengths whatever the goal.
        CHECK(std::abs(Length(position(nodes, 1) - position(nodes, 0)) - 1) < 1e-4f);
        CHECK(std::abs(Length(position(nodes, 2) - position(nodes, 1)) - 1) < 1e-4f);
        CHECK(std::abs(Length(position(nodes, 3) - position(nodes, 2)) - 0.25f) < 1e-4f);
        return nodes;
    };
    IkGoal goal;
    goal.target = Vec3(1.2f, 0, 0);
    // A straight arm folds; the pole picks the side the elbow goes to.
    goal.pole = Vec3(0, 1, 0);
    std::vector<Mat4> nodes = solve(goal);
    CHECK(Near(position(nodes, 2), goal.target, 1e-4f) && position(nodes, 1).y > 0.5f && std::abs(position(nodes, 1).z) < 1e-4f);
    goal.pole = Vec3(0, 0, -1);
    nodes = solve(goal);
    CHECK(Near(position(nodes, 2), goal.target, 1e-4f) && position(nodes, 1).z < -0.5f && std::abs(position(nodes, 1).y) < 1e-4f);
    CHECK(Near(position(nodes, 0), Vec3(0, 0, 0), 1e-6f));  // the shoulder turns, it does not move
    goal.pole = Vec3();
    goal.target = Vec3(0.6f, 1.1f, -0.4f);
    nodes = solve(goal);
    CHECK(Near(position(nodes, 2), goal.target, 1e-4f));
    // Out of reach: the arm stretches towards the goal.
    goal.target = Vec3(0, 5, 0);
    nodes = solve(goal);
    CHECK(Near(position(nodes, 2), Vec3(0, 2, 0), 1e-2f) && Near(position(nodes, 3), Vec3(0, 2.25f, 0), 2e-2f));
    // Half weight reaches half way; zero leaves the pose alone.
    goal.target = Vec3(1, 1, 0);
    goal.weight = 0.5f;
    nodes = solve(goal);
    CHECK(Near(position(nodes, 2), Vec3(1.5f, 0.5f, 0), 1e-4f));
    goal.weight = 0;
    nodes = solve(goal);
    CHECK(Near(position(nodes, 2), Vec3(2, 0, 0), 1e-6f));
    // matchRotation turns the hand (and its finger) to the goal's orientation.
    goal.weight = 1;
    goal.matchRotation = true;
    goal.rotation = Mat4::RotationEuler(Vec3(0, 0, 90));
    nodes = solve(goal);
    CHECK(Near(position(nodes, 2), Vec3(1, 1, 0), 1e-4f) && Near(position(nodes, 3), Vec3(1, 1.25f, 0), 1e-4f));
    goal.matchRotation = false;
    // soften eases into full extension: exact below the soft zone, short of the goal inside it, never past the length.
    goal.pole = Vec3(0, 1, 0);
    goal.soften = 0.1f;  // the last 0.2 of this 2-unit arm
    goal.target = Vec3(1.7f, 0, 0);
    CHECK(Near(position(solve(goal), 2), goal.target, 1e-4f));
    goal.target = Vec3(1.9f, 0, 0);
    CHECK(Near(position(solve(goal), 2), Vec3(2 - 0.2f * std::exp(-0.5f), 0, 0), 1e-4f));
    goal.target = Vec3(2.0f, 0, 0);
    const float atLength = position(solve(goal), 2).x;
    goal.target = Vec3(2.1f, 0, 0);
    const float beyond = position(solve(goal), 2).x;
    CHECK(atLength > 1.9f && beyond > atLength && beyond < 2 && position(solve(goal), 1).y > 0.2f);  // still bent, no snap
    goal.soften = 0;
    goal.pole = Vec3();
    // Without a pole the limb bends to the side it bends in the model's default pose, also when the
    // clip has pushed it slightly the other way; with neither, the posed side decides.
    {
        Mesh bent = mesh, posed = mesh;
        bent.nodes[1].translation = Vec3(1, 0.2f, 0);
        bent.nodes[2].translation = Vec3(1, -0.2f, 0);
        posed.nodes[1].translation = Vec3(1, -0.02f, 0);
        posed.nodes[2].translation = Vec3(1, 0.02f, 0);
        const std::vector<Mat4> rest = EvaluateNodePose(bent, nullptr, 0);
        IkGoal fold;
        fold.node = 2;
        fold.target = Vec3(1.5f, 0, 0);
        std::vector<Mat4> pose = EvaluateNodePose(posed, nullptr, 0);
        SolveIk(posed, pose, fold, &rest);
        CHECK(Near(position(pose, 2), fold.target, 1e-4f) && position(pose, 1).y > 0.5f);
        pose = EvaluateNodePose(posed, nullptr, 0);
        SolveIk(posed, pose, fold);
        CHECK(Near(position(pose, 2), fold.target, 1e-4f) && position(pose, 1).y < -0.5f);
    }
    // One bone aims; three bones descend to the goal; a chain longer than the skeleton does nothing.
    goal.chain = 1;
    goal.target = Vec3(1, 3, 0);
    nodes = solve(goal);
    CHECK(Near(position(nodes, 1), Vec3(1, 0, 0), 1e-6f) && Near(position(nodes, 2), Vec3(1, 1, 0), 1e-4f));
    goal.node = 3;
    goal.chain = 3;
    goal.target = Vec3(0.8f, 1.2f, 0.5f);
    nodes = solve(goal);
    CHECK(Near(position(nodes, 3), goal.target, 2e-3f));
    std::vector<Mat4> again = solve(goal);
    CHECK(std::memcmp(nodes.data(), again.data(), nodes.size() * sizeof(Mat4)) == 0);
    goal.chain = 4;
    nodes = solve(goal);
    CHECK(Near(position(nodes, 3), Vec3(2.25f, 0, 0), 1e-6f));
}

TEST(BoneAttachmentAndIkOnModels) {
    Engine e;
    std::string err;
    CHECK(e.Open(TempProject("bone_ik"), &err));
    Call(e, "scene.new", R"J({"empty":true})J");
    std::string text = kRigFbx;
    text.replace(text.find("%TEXTURE%"), 9, "");
    const std::string path = JoinPath(e.ProjectDir(), "assets/models/rig.fbx");
    CreateDirectories(ParentPath(path));
    CHECK(WriteTextFile(path, text));
    Call(e, "entity.create", R"J({"name":"Rig","components":{"Transform":{"position":[10,0,0]},"MeshRenderer":{"mesh":"assets/models/rig.fbx","unlit":true},
                                 "Animator":{"clip":"Wave","playing":false}}})J");
    Call(e, "entity.create", R"J({"name":"Hat","parent":"Rig","components":{"Transform":{"scale":[0.2,0.2,0.2]},"MeshRenderer":{"mesh":"cube"},
                                 "BoneAttachment":{"bone":"Tip","position":[0,0.2,0]}}})J");
    EntityId hat = e.GetScene().FindByName("Hat");
    CHECK(e.GetScene().Record(hat)->parent == e.GetScene().FindByName("Rig"));
    auto bones = [&](const char* args) { return Call(e, "animation.bones", args)["result"]; };
    auto vec = [](const Json& v) { return Vec3(v[0].asFloat(), v[1].asFloat(), v[2].asFloat()); };
    auto boneNamed = [&](const Json& list, const char* name) {
        for (size_t i = 0; i < list["bones"].size(); ++i) if (list["bones"][i]["name"].asString() == name) return list["bones"][i];
        return Json();
    };
    // Names, parents and world positions (the entity stands at x = 10).
    Json all = bones(R"J({"id":"Rig"})J");
    CHECK(boneNamed(all, "Tip")["parent"].asString() == "Root" && Near(vec(boneNamed(all, "Tip")["position"]), Vec3(10, 1, 0), 1e-4f));
    CHECK(Near(vec(boneNamed(all, "Root")["position"]), Vec3(10, 0, 0), 1e-4f) && all["goals"].size() == 0);
    CHECK(Near(vec(boneNamed(all, "Tip")["modelPosition"]), Vec3(0, 1, 0), 1e-4f));  // where a child entity stands to be on the bone
    CHECK(all["attachments"].size() == 1 && all["attachments"][0]["found"].asBool() && all["attachments"][0]["name"].asString() == "Hat");
    CHECK(bones(R"J({"id":"Rig","bone":"Tip"})J")["bones"].size() == 1);
    CHECK(Call(e, "animation.bones", R"J({"id":"Rig","bone":"Nose"})J")["error"]["code"].asString() == "bone_not_found");
    CHECK(Call(e, "animation.bones", R"J({"id":"Hat"})J")["ok"].asBool());  // built-in meshes simply have no bones

    // The attachment follows the bone after a step, through the clip...
    Call(e, "sim.step", R"J({"frames":1})J");
    CHECK(Near(e.GetScene().Get<Transform>(hat)->position, Vec3(0, 1.2f, 0), 1e-4f));
    CHECK(Near(e.GetScene().Get<Transform>(hat)->scale, Vec3(0.2f, 0.2f, 0.2f), 1e-6f));
    Call(e, "component.set", R"J({"id":"Rig","type":"Animator","values":{"time":1}})J");
    Call(e, "sim.step", R"J({"frames":1})J");
    CHECK(Near(e.GetScene().Get<Transform>(hat)->position, Vec3(0.5f, 1.2f, 0), 1e-4f));
    CHECK(Near(e.GetScene().WorldMatrix(hat).TransformPoint(Vec3(0, 0, 0)), Vec3(10.5f, 1.2f, 0), 1e-4f));
    Json eval = Json::MakeObject();
    eval["code"] = "local b = animation.bone(scene.find('Rig'), 'Tip'); "
                   "return b.position.x * 100 + b.position.y + (animation.bone(scene.find('Rig'), 'Nose') == nil and 0 or 5000)";
    Json lua = e.Call("script.eval", eval);
    CHECK(std::abs(lua["result"]["value"].asNumber() - 1051) < 1e-3);
    Call(e, "sim.stop");

    // ...and through IK: a goal entity pulls the upper bone down to the side.
    Call(e, "component.set", R"J({"id":"Rig","type":"Animator","values":{"time":0}})J");
    RenderTarget before = RenderLook(e, Vec3(10.5f, 0.5f, 4), Vec3(10.5f, 0.5f, 0));
    Call(e, "entity.create", R"J({"name":"Goal","parent":"Rig","components":{"Transform":{"position":[1,0,0]},"BoneIK":{"bone":"Tip","chain":1}}})J");
    Json solved = bones(R"J({"id":"Rig","bone":"Tip"})J");
    CHECK(Near(vec(solved["bones"][0]["position"]), Vec3(11, 0, 0), 1e-4f));
    // ik:false is the clip alone: what a foot-placement script adds the ground height to.
    CHECK(Near(vec(bones(R"J({"id":"Rig","bone":"Tip","ik":false})J")["bones"][0]["position"]), Vec3(10, 1, 0), 1e-4f));
    Call(e, "sim.play");
    eval["code"] = "local rig = scene.find('Rig'); local a, b = animation.bone(rig, 'Tip'), animation.bone(rig, 'Tip', {ik = false}); "
                   "return a.position.x * 100 + b.position.x + b.modelPosition.y * 0.5";
    CHECK(std::abs(e.Call("script.eval", eval)["result"]["value"].asNumber() - 1110.5) < 1e-3);
    Call(e, "sim.stop");
    CHECK(solved["goals"].size() == 1 && solved["goals"][0]["found"].asBool() && solved["goals"][0]["distance"].asFloat() < 1e-4f);
    // Outside play an edit is enough to move what a bone holds.
    CHECK(Near(e.GetScene().Get<Transform>(hat)->position, Vec3(1.2f, 0, 0), 1e-4f));
    RenderTarget after = RenderLook(e, Vec3(10.5f, 0.5f, 4), Vec3(10.5f, 0.5f, 0));
    CHECK(before.Hash() != after.Hash());
    CHECK(WritePng("build/bone-ik.png", after.ToImage(), true));
    Json state = Call(e, "animation.state", R"J({"id":"Rig","pose":true})J")["result"];
    CHECK(state["jointMatrices"].size() == 2 && std::abs(state["jointMatrices"][0][1].asFloat() + 1) < 1e-4f);  // Root turned -90 degrees about z
    Call(e, "sim.step", R"J({"frames":1})J");
    CHECK(Near(e.GetScene().Get<Transform>(hat)->position, Vec3(1.2f, 0, 0), 1e-4f));
    CHECK(std::abs(std::abs(e.GetScene().Get<Transform>(hat)->rotation.z) - 90) < 1e-2f);
    // An unreachable goal and an unknown bone.
    Call(e, "sim.stop");
    Call(e, "component.set", R"J({"id":"Goal","type":"Transform","values":{"position":[3,0,0]}})J");
    solved = bones(R"J({"id":"Rig","bone":"Tip"})J");
    CHECK(Near(vec(solved["bones"][0]["position"]), Vec3(11, 0, 0), 1e-4f) && std::abs(solved["goals"][0]["distance"].asFloat() - 2) < 1e-4f);
    Call(e, "component.set", R"J({"id":"Goal","type":"BoneIK","values":{"bone":"Nose"}})J");
    solved = bones(R"J({"id":"Rig","bone":"Tip"})J");
    CHECK(!solved["goals"][0]["found"].asBool() && Near(vec(solved["bones"][0]["position"]), Vec3(10, 1, 0), 1e-4f));
    // Both are ordinary reflected components.
    Json saved = e.GetScene().EntityToJson(e.GetScene().FindByName("Goal"));
    CHECK(saved["components"]["BoneIK"]["bone"].asString() == "Nose" && saved["components"]["BoneIK"]["chain"].asInt() == 1);
}

TEST(AnimationPoseInterpolation) {
    Mesh mesh;
    mesh.nodes.resize(2);
    mesh.nodes[0].parent = 1;  // parents may occur after children in the source
    mesh.nodes[0].scale = Vec3(2, 1, 1);
    mesh.nodes[1].usesMatrix = true;
    mesh.nodes[1].matrix = Mat4::Translation(Vec3(3, 0, 0));
    mesh.joints.push_back({0, Mat4::Translation(Vec3(-1, 0, 0))});
    AnimationChannel channel;
    channel.node = 0;
    channel.times = {0, 2};
    channel.values = {Vec4(0,0,0,0), Vec4(4,0,0,0)};
    AnimationClip clip;
    clip.channels.push_back(channel);
    auto sample = [&](float time) { return EvaluateAnimationPose(mesh, &clip, time)[0]; };
    CHECK(Near(sample(1).TransformPoint(Vec3(1,0,0)), Vec3(5,0,0), 1e-5f));
    CHECK(Near(sample(-8).TransformPoint(Vec3(1,0,0)), Vec3(3,0,0), 1e-5f));
    CHECK(Near(sample(8).TransformPoint(Vec3(1,0,0)), Vec3(7,0,0), 1e-5f));
    CHECK(Near(sample(1).TransformDir(Vec3(1,0,0)), Vec3(2,0,0), 1e-5f));  // unanimated scale retained
    clip.channels[0].interpolation = AnimationInterpolation::Step;
    CHECK(Near(sample(1.999f).TransformPoint(Vec3(1,0,0)), Vec3(3,0,0), 1e-5f));
    CHECK(Near(sample(2).TransformPoint(Vec3(1,0,0)), Vec3(7,0,0), 1e-5f));
    clip.channels[0].interpolation = AnimationInterpolation::CubicSpline;
    clip.channels[0].values = {Vec4(), Vec4(), Vec4(2,0,0,0), Vec4(), Vec4(4,0,0,0), Vec4()};
    CHECK(Near(sample(1).TransformPoint(Vec3(1,0,0)), Vec3(5.5f,0,0), 1e-5f));  // tangent scaled by two seconds
    clip.channels[0].path = AnimationPath::Rotation;
    clip.channels[0].interpolation = AnimationInterpolation::Linear;
    clip.channels[0].values = {Vec4(0,0,0,1), Vec4(0,0,1,0)};
    CHECK(Near(sample(1).TransformDir(Vec3(1,0,0)), Vec3(0,2,0), 1e-5f));
    // Quaternion signs represent the same rotation; interpolation takes the shortest arc.
    clip.channels[0].values[1] = Vec4(0,0,0,-1);
    CHECK(Near(sample(1).TransformDir(Vec3(1,0,0)), Vec3(2,0,0), 1e-5f));
    clip.channels[0].interpolation = AnimationInterpolation::CubicSpline;
    clip.channels[0].values = {Vec4(), Vec4(0,0,0,1), Vec4(), Vec4(), Vec4(0,0,1,0), Vec4()};
    CHECK(Near(sample(1).TransformDir(Vec3(1,0,0)), Vec3(0,2,0), 1e-5f));  // interpolated quaternion normalized
    clip.channels[0].path = AnimationPath::Scale;
    clip.channels[0].interpolation = AnimationInterpolation::Linear;
    clip.channels[0].values = {Vec4(1,1,1,0), Vec4(3,3,3,0)};
    CHECK(Near(sample(1).TransformDir(Vec3(0,1,0)), Vec3(0,2,0), 1e-5f));
    CHECK(Near(EvaluateAnimationPose(mesh, nullptr, 0)[0].TransformPoint(Vec3(1,0,0)), Vec3(3,0,0), 1e-5f));
}

TEST(AnimatorCommandsAndLua) {
    Engine e;
    std::string err;
    CHECK(e.Open(TempProject("animator"), &err));
    CHECK(CopyFileTo(TestSourceDir() + "/tests/fixtures/Showcase/assets/models/fox.glb", JoinPath(e.ProjectDir(), "assets/models/fox.glb")));
    Call(e, "scene.new", R"J({"empty":true})J");
    Call(e, "entity.create", R"J({"name":"Fox","components":{"MeshRenderer":{"mesh":"assets/models/fox.glb"}}})J");
    EntityId id = e.GetScene().FindByName("Fox");
    CHECK(Call(e, "animation.play", R"J({"id":"Fox","clip":"missing"})J")["error"]["code"].asString() == "animation_not_found");
    CHECK(e.GetScene().Get<Animator>(id) == nullptr);
    CHECK(Call(e, "animation.play", R"J({"id":"Fox","clip":"Walk"})J")["ok"].asBool());
    Json saved = e.GetScene().ToJson();
    Scene restored;
    CHECK(restored.FromJson(saved, &err) && restored.Get<Animator>(id)->clip == "Walk");
    CHECK(Call(e, "history.undo", "{}")["ok"].asBool());
    CHECK(e.GetScene().Get<Animator>(id) == nullptr);
    CHECK(Call(e, "history.redo", "{}")["ok"].asBool());
    CHECK(e.GetScene().Get<Animator>(id)->clip == "Walk");
    Call(e, "sim.step", R"J({"frames":12})J");
    Json state = Call(e, "animation.state", R"J({"id":"Fox","pose":true})J")["result"];
    CHECK(std::fabs(state["time"].asFloat() - 0.2f) < 1e-6f && state["validClip"].asBool());
    CHECK(state["jointMatrices"].size() == 24 && state["jointMatrices"][0].size() == 16);
    Json pose = state["jointMatrices"];
    Call(e, "component.set", R"J({"id":"Fox","type":"Animator","values":{"playing":false}})J");
    Call(e, "sim.step", R"J({"frames":10})J");
    CHECK(Call(e, "animation.state", R"J({"id":"Fox","pose":true})J")["result"]["jointMatrices"] == pose);
    Call(e, "animation.play", R"J({"id":"Fox","clip":"Walk","loop":false})J");
    Call(e, "sim.step", R"J({"frames":60})J");
    state = Call(e, "animation.state", R"J({"id":"Fox"})J")["result"];
    CHECK(!state["playing"].asBool() && state["time"] == state["duration"]);
    CHECK(Call(e, "script.eval", R"J({"code":"animation.play('Fox', 'Walk', {speed=-1, loop=false})"})J")["ok"].asBool());
    Call(e, "sim.step", R"J({"frames":60})J");
    state = Call(e, "animation.state", R"J({"id":"Fox"})J")["result"];
    CHECK(!state["playing"].asBool() && state["time"].asFloat() == 0);
    Call(e, "animation.play", R"J({"id":"Fox","clip":"Run","speed":-1,"loop":true})J");
    Call(e, "component.set", R"J({"id":"Fox","type":"Animator","values":{"time":0}})J");
    Call(e, "sim.step", R"J({"frames":1})J");
    state = Call(e, "animation.state", R"J({"id":"Fox"})J")["result"];
    CHECK(std::fabs(state["time"].asFloat() - state["duration"].asFloat() + 1.0f/60) < 1e-6f);
    Call(e, "animation.play", R"J({"id":"Fox","clip":"Run","speed":1})J");
    Call(e, "sim.step", R"J({"frames":24})J");
    Json first = Call(e, "animation.state", R"J({"id":"Fox","pose":true})J")["result"];
    Call(e, "animation.play", R"J({"id":"Fox","clip":"Run","restart":false})J");
    CHECK(e.GetScene().Get<Animator>(id)->time == first["time"].asFloat());
    Call(e, "animation.play", R"J({"id":"Fox","clip":"Run"})J");
    Call(e, "sim.step", R"J({"frames":24})J");
    CHECK(Call(e, "animation.state", R"J({"id":"Fox","pose":true})J")["result"] == first);
    CHECK(Call(e, "script.eval", R"J({"code":"local ok = pcall(animation.play, 'Fox', 'invalid'); assert(not ok)"})J")["ok"].asBool());
    // self:play follows the same command path from a real script instance.
    CHECK(WriteTextFile(JoinPath(e.ProjectDir(), "scripts/animate.lua"), "return {onStart=function(self) self:play('Survey', {speed=0}) end}"));
    Call(e, "component.add", R"J({"id":"Fox","type":"Script","values":{"path":"scripts/animate.lua"}})J");
    Call(e, "sim.step", R"J({"frames":1})J");
    CHECK(e.GetScene().Get<Animator>(id)->clip == "Survey" && e.GetScene().Get<Animator>(id)->time == 0);
    CHECK(e.Scripts().Errors().empty());
}

TEST(ParticleSimulationAndCommands) {
    Engine e;
    std::string err;
    CHECK(e.Open(TempProject("particles"), &err));
    EmitterCall(e, "scene.new", R"J({"empty":true})J");
    CHECK(EmitterCall(e, "entity.create", R"J({"name":"Effect","components":{"Transform":{"position":[3,4,0]},"EmitterSettings":{"rate":0,"burst":2,"lifetime":0.5,"speed":2,"spread":0,"gravity":[0,-2,0],"maxParticles":3,"dimensions":2,"loop":false}}})J")["ok"].asBool());
    EntityId id = e.GetScene().FindByName("Effect");
    EmitterCall(e, "sim.step", R"J({"frames":1})J");
    Json state = EmitterCall(e, "vfx.state", R"J({"id":"Effect","particles":true})J")["result"];
    CHECK(state["count"].asInt() == 2 && state["emitted"].asInt() == 2);
    CHECK(state["particles"][0]["age"].asFloat() == 0 && state["particles"][0]["position"][1].asFloat() == 0);
    CHECK(state["particles"][0]["velocity"][1].asFloat() == 2 && state["particles"][0]["velocity"][2].asFloat() == 0);
    CHECK(EmitterCall(e, "vfx.burst", R"J({"id":"Effect","count":10})J")["result"]["accepted"].asInt() == 1);
    CHECK(EmitterCall(e, "vfx.burst", R"J({"id":"Effect","count":1})J")["result"]["accepted"].asInt() == 0);
    CHECK(!EmitterCall(e, "vfx.burst", R"J({"id":"Effect","count":10001})J")["ok"].asBool());
    CHECK(!EmitterCall(e, "vfx.burst", R"J({"id":"Effect","count":-1})J")["ok"].asBool());
    CHECK(!EmitterCall(e, "vfx.burst", R"J({"id":"Effect","count":1.5})J")["ok"].asBool());
    EmitterCall(e, "component.set", R"J({"id":"Effect","type":"EmitterSettings","values":{"playing":false}})J");
    EmitterCall(e, "sim.step", R"J({"frames":1})J");
    state = EmitterCall(e, "vfx.state", R"J({"id":"Effect","particles":true})J")["result"];
    CHECK(std::fabs(state["particles"][0]["age"].asFloat() - 1.0f/60) < 1e-6f);
    CHECK(std::fabs(state["particles"][0]["velocity"][1].asFloat() - (2 - 2.0f/60)) < 1e-6f);
    CHECK(state["particles"][0]["position"][1].asFloat() > 0);
    EmitterCall(e, "sim.step", R"J({"frames":31})J");
    CHECK(EmitterCall(e, "vfx.state", R"J({"id":"Effect"})J")["result"]["count"].asInt() == 0);
    EmitterCall(e, "vfx.clear", R"J({"id":"Effect","restart":true})J");
    EmitterCall(e, "component.set", R"J({"id":"Effect","type":"EmitterSettings","values":{"space":"world","playing":true}})J");
    EmitterCall(e, "sim.step", R"J({"frames":1})J");
    state = EmitterCall(e, "vfx.state", R"J({"id":"Effect","particles":true})J")["result"];
    CHECK(state["particles"][0]["worldSpace"].asBool() && state["particles"][0]["position"][0].asFloat() == 3);
    EmitterCall(e, "component.set", R"J({"id":"Effect","type":"Transform","values":{"position":[8,4,0]}})J");
    CHECK(TestEmitter(e.GetScene(), id)->particles[0].position.x == 3);
    Json serialized = e.GetScene().ToJson();
    Scene restored;
    CHECK(restored.FromJson(serialized, &err));
    CHECK(restored.Get<VFXSystem>(id)->emitters.empty() && !restored.Get<VFXSystem>(id)->asset.empty());
    EmitterCall(e, "vfx.clear", R"J({"id":"Effect"})J");
    EmitterCall(e, "component.set", R"J({"id":"Effect","type":"EmitterSettings","values":{"maxParticles":10,"loop":true,"rate":6,"lifetime":10}})J");
    EmitterCall(e, "sim.step", R"J({"frames":60})J");
    CHECK(EmitterCall(e, "vfx.state", R"J({"id":"Effect"})J")["result"]["count"].asInt() == 6);
    EmitterCall(e, "component.set", R"J({"id":"Effect","type":"EmitterSettings","values":{"maxParticles":1}})J");
    EmitterCall(e, "sim.step", R"J({"frames":1})J");
    CHECK(EmitterCall(e, "vfx.state", R"J({"id":"Effect"})J")["result"]["count"].asInt() == 1);
    CHECK(EmitterCall(e, "script.eval", R"J({"code":"assert(vfx.burst('Effect', 5) == 0); assert(not pcall(vfx.burst, 'Effect', -1))"})J")["ok"].asBool());
    EmitterCall(e, "vfx.clear", R"J({"id":"Effect"})J");
    CHECK(WriteTextFile(JoinPath(e.ProjectDir(), "scripts/burst.lua"), "return {onStart=function(self) assert(vfx.burst(self.id, 1) == 1) end}"));
    EmitterCall(e, "component.add", R"J({"id":"Effect","type":"Script","values":{"path":"scripts/burst.lua"}})J");
    EmitterCall(e, "sim.step", R"J({"frames":1})J");
    CHECK(EmitterCall(e, "vfx.state", R"J({"id":"Effect"})J")["result"]["count"].asInt() == 1 && e.Scripts().Errors().empty());
    CHECK(EmitterCall(e, "component.set", R"J({"id":"Effect","type":"EmitterSettings","values":{"gravity":[0,1e100,0]}})J")["error"]["code"].asString() == "invalid_range");
    TestEmitter(e.GetScene(), id)->gravity.y = std::numeric_limits<float>::infinity();  // legacy/programmatic data still has a runtime guard
    CHECK(EmitterCall(e, "vfx.burst", R"J({"id":"Effect","count":1})J")["error"]["code"].asString() == "invalid_emitter");
}

TEST(ParticleRandomStreamIsDeterministic) {
    auto simulate = [](int seed) {
        Engine e;
        EmitterCall(e, "scene.new", R"J({"empty":true})J");
        Json args = Json::parse(R"J({"name":"Effect","components":{"EmitterSettings":{"rate":0,"burst":10,"loop":false,"spread":90,"gravity":[0,0,0],"lifetime":10}}})J");
        args["components"]["EmitterSettings"]["seed"] = seed;
        EmitterCall(e, "entity.create", args);
        EmitterCall(e, "sim.step", R"J({"frames":15})J");
        return EmitterCall(e, "vfx.state", R"J({"id":"Effect","particles":true})J")["result"];
    };
    Json first = simulate(7);
    CHECK(first == simulate(7) && first != simulate(8));
    CHECK(first["count"].asInt() == 10);
    for (const Json& particle : first["particles"].items()) {
        const Json& v = particle["velocity"];
        float length = std::sqrt(v[0].asFloat()*v[0].asFloat() + v[1].asFloat()*v[1].asFloat() + v[2].asFloat()*v[2].asFloat());
        CHECK(std::fabs(length - 1) < 1e-5f && v[1].asFloat() >= -1e-6f);
    }
}

TEST(ShadingShadowsAndLights) {
    Engine e;
    e.Call("scene.new", Json::parse(R"J({"empty": true})J"));
    Call(e, "entity.create", R"J({"name": "Sun", "components": {"Transform": {"rotation": [-70, 20, 0]}, "DirectionalLight": {"shadowStrength": 1}}})J");
    Call(e, "entity.create", R"J({"name": "Ground", "components": {"Transform": {"scale": [10, 1, 10]}, "MeshRenderer": {"mesh": "plane"}}})J");
    Call(e, "entity.create", R"J({"name": "Ball", "components": {"Transform": {"position": [0, 1, 0], "scale": [1.5, 1.5, 1.5]}, "MeshRenderer": {"mesh": "sphere"}}})J");
    Vec3 eye(0, 6, 7), at(0, 0, 0);
    RenderTarget withShadow = RenderLook(e, eye, at);
    Call(e, "component.set", R"J({"id": "Sun", "type": "DirectionalLight", "values": {"shadows": false}})J");
    RenderTarget noShadow = RenderLook(e, eye, at);
    CHECK(MeanLuma(withShadow) < MeanLuma(noShadow) - 0.5);
    Call(e, "component.set", R"J({"id": "Ball", "type": "MeshRenderer", "values": {"shading": "flat"}})J");
    RenderTarget flat = RenderLook(e, eye, at);
    CHECK(flat.Hash() != noShadow.Hash());
    Call(e, "entity.create", R"J({"name": "Lamp", "components": {"Transform": {"position": [2, 0.5, 2]}, "PointLight": {"intensity": 3, "range": 4}}})J");
    RenderTarget lamp = RenderLook(e, eye, at);
    CHECK(MeanLuma(lamp) > MeanLuma(flat) + 1.0);
}

TEST(OrthographicAndFollowCamera) {
    Engine e;
    std::string err;
    CHECK(e.Open(TempProject("follow_camera"), &err));  // the runner below moves through a project script
    e.Call("scene.new", Json::parse(R"J({"empty": true})J"));
    Call(e, "entity.create", R"J({"name": "Cam", "components": {"Transform": {"position": [0, 0, 5]}, "Camera": {"projection": "orthographic", "orthoSize": 3}}})J");
    Call(e, "entity.create", R"J({"name": "Box", "components": {"MeshRenderer": {}}})J");
    EntityId box = e.GetScene().FindByName("Box");
    auto coverage = [&]() {
        RenderTarget rt;
        rt.Resize(160, 90);
        e.RenderGameView(rt);
        return CountId(rt, box);
    };
    size_t near1 = coverage();
    Call(e, "component.set", R"J({"id": "Box", "type": "Transform", "values": {"position": [0, 0, -10]}})J");
    size_t far1 = coverage();
    CHECK(near1 > 200 && near1 == far1);  // orthographic: size does not depend on distance
    Call(e, "component.set", R"J({"id": "Cam", "type": "Camera", "values": {"projection": "perspective"}})J");
    CHECK(coverage() < far1 / 4);

    // CameraFollow keeps the camera at target + offset and aims at the target.
    Call(e, "script.write", R"J({"path": "scripts/runner.lua", "source": "local M = {}\nfunction M:onUpdate(dt) self:translate(3 * dt, 0, 0) end\nreturn M\n"})J");
    Call(e, "entity.create", R"J({"name": "Runner", "components": {"Transform": {"position": [0, 0.5, 0]}, "Script": {"path": "scripts/runner.lua"}}})J");
    EntityId runner = e.GetScene().FindByName("Runner");
    Json args = Json::parse(R"J({"id": "Cam", "type": "CameraFollow", "values": {"offset": [0, 3, 6], "smoothing": 0}})J");
    args["values"]["target"] = runner;
    e.Call("component.add", args);
    Call(e, "sim.step", R"J({"frames": 60})J");
    Vec3 cam = PosOf(e, "Cam"), run = PosOf(e, "Runner");
    CHECK(Near(cam, run + Vec3(0, 3, 6), 1e-3f));
    Vec3 fwd = ForwardFromEuler(e.GetScene().Get<Transform>(e.GetScene().FindByName("Cam"))->rotation);
    CHECK(Dot(fwd, Normalize(run + Vec3(0, 0.5f, 0) - cam)) > 0.999f);
}

TEST(RenderInterpolation) {
    // Windows draw between fixed steps: Begin/EndInterpolatedRender put each Transform between its
    // previous and current step for the frame, then restore the simulated value exactly.
    Engine e;
    std::string err;
    CHECK(e.Open(TestSourceDir() + "/tests/fixtures/Hello", &err));
    CHECK(Call(e, "entity.create", R"({"name":"Ball","components":{"Transform":{"position":[40,30,40]},"Collider":{"shape":"sphere"},"RigidBody":{}}})")["ok"].asBool());
    EntityId ball = e.GetScene().FindByName("Ball");
    e.Play();
    e.Tick(Engine::kFixedDt * 10);  // falling by now
    e.Tick(Engine::kFixedDt * 1.5);  // one more step, half a step left over
    const float simulated = e.GetScene().Get<Transform>(ball)->position.y;
    e.BeginInterpolatedRender();
    const float drawn = e.GetScene().Get<Transform>(ball)->position.y;
    e.EndInterpolatedRender();
    CHECK(drawn > simulated && drawn - simulated < 0.1f);  // between the previous (higher) step and this one
    CHECK(e.GetScene().Get<Transform>(ball)->position.y == simulated);
    // Tools step exactly: what they draw is the simulated state.
    e.Step(1);
    const float stepped = e.GetScene().Get<Transform>(ball)->position.y;
    e.BeginInterpolatedRender();
    CHECK(e.GetScene().Get<Transform>(ball)->position.y == stepped);
    e.EndInterpolatedRender();
    e.Stop();
}

TEST(DebugDrawing) {
    Engine e;
    std::string err;
    CHECK(e.Open(TempProject("debugdraw"), &err));
    e.Call("scene.new", Json());
    auto hash = [&]() { return Call(e, "render.screenshot", R"J({"width": 96, "height": 54, "inline": false})J")["result"]["hash"].asString(); };
    Call(e, "sim.step", R"J({"frames": 1})J");
    std::string clean = hash();
    CHECK(Call(e, "debug.draw", R"J({"boxes": [{"center": [0, 1, 0], "size": [2, 2, 2], "color": [1, 0, 0]}], "seconds": 0.5})J")["result"]["added"].asInt() == 12);
    CHECK(hash() != clean);
    Call(e, "sim.step", R"J({"frames": 40})J");  // expired
    CHECK(hash() == clean);
    // Lua: 0-second lines last one simulated frame.
    Call(e, "script.eval", R"J({"code": "draw.sphere({x = 0, y = 1, z = 0}, 1, {1, 1, 0})"})J");
    CHECK(e.DebugLineCount() == 72);
    Call(e, "sim.step", R"J({"frames": 1})J");
    CHECK(e.DebugLineCount() == 0);
}

TEST(ShowcaseFoxModel) {
    // Completion check for rendering: the external glTF character (tests/fixtures/Showcase) is drawn with its texture.
    Engine e;
    std::string err;
    CHECK(e.Open(TestSourceDir() + "/tests/fixtures/Showcase", &err));
    Json info = Call(e, "asset.info", R"J({"path": "assets/models/fox.glb"})J")["result"];
    CHECK(info["triangles"].asInt() == 576 && info["textures"][0][0].asInt() == 1024);
    CHECK(info["joints"].asInt() == 24 && info["clips"].size() == 3);
    CHECK(info["clips"][0]["name"].asString() == "Survey" && info["clips"][1]["name"].asString() == "Walk" &&
          info["clips"][2]["name"].asString() == "Run");
    CHECK(info["clips"][1]["duration"].asFloat() > 0.7f && info["clips"][1]["channels"].asInt() == 21);
    RenderTarget rt;
    rt.Resize(320, 180);
    e.RenderGameView(rt);
    EntityId fox = e.GetScene().FindByName("Fox");
    CHECK(CountId(rt, fox) > 100);
    // Textured: the fox's pixels are not all one color.
    std::set<uint32_t> colors;
    for (size_t i = 0; i < rt.ids.size(); ++i) {
        if (rt.ids[i] == fox) colors.insert(rt.color[i]);
    }
    CHECK(colors.size() > 20);
    CHECK(e.Scripts().Errors().empty());
    // Multi-threaded rendering is bit-identical to a single thread.
    SetMaxRenderThreads(1);
    RenderTarget single;
    single.Resize(320, 180);
    e.RenderGameView(single);
    SetMaxRenderThreads(16);
    CHECK(single.Hash() == rt.Hash());
}

TEST(ShowcaseAnimationControls) {
    auto play = []() {
        Engine e;
        std::string err;
        CHECK(e.Open(TestSourceDir() + "/tests/fixtures/Showcase", &err));
        EntityId fox = e.GetScene().FindByName("Fox");
        Call(e, "sim.step", R"J({"frames":1})J");
        CHECK(e.GetScene().Get<Animator>(fox)->clip == "Survey");
        Call(e, "input.key", R"J({"key":"W","down":true})J");
        Call(e, "sim.step", R"J({"frames":12})J");
        CHECK(e.GetScene().Get<Animator>(fox)->clip == "Walk");
        float walkTime = e.GetScene().Get<Animator>(fox)->time;
        Call(e, "sim.step", R"J({"frames":1})J");
        CHECK(e.GetScene().Get<Animator>(fox)->time > walkTime);  // no restart each update
        Call(e, "input.key", R"J({"key":"Shift","down":true})J");
        Call(e, "sim.step", R"J({"frames":12})J");
        CHECK(e.GetScene().Get<Animator>(fox)->clip == "Run");
        RenderTarget rt;
        rt.Resize(320,180);
        e.RenderGameView(rt);
        uint64_t runHash = rt.Hash();
        Call(e, "input.key", R"J({"key":"W","down":false})J");
        Call(e, "input.key", R"J({"key":"Shift","down":false})J");
        Call(e, "sim.step", R"J({"frames":1})J");
        CHECK(e.GetScene().Get<Animator>(fox)->clip == "Survey");
        CHECK(e.Scripts().Errors().empty());
        return runHash;
    };
    uint64_t first = play();
    CHECK(first == play());
    std::printf("  animated Showcase hash %016llx\n", static_cast<unsigned long long>(first));
}

TEST(ShowcasePostProcessControls) {
    Engine e;
    std::string err;
    CHECK(e.Open(TestSourceDir() + "/tests/fixtures/Showcase", &err));
    const EntityId camera = e.GetScene().FindByName("Main Camera");
    CHECK(!e.GetScene().Get<PostProcess>(camera)->fxaa);
    Call(e, "sim.step", R"J({"frames":1})J");
    for (int mode : {2, 3, 4, 5, 6, 1}) {
        const std::string key = std::to_string(mode);
        CHECK(e.Call("input.key", Json::parse("{\"key\":\"" + key + "\",\"down\":true}"))["ok"].asBool());
        Call(e, "sim.step", R"J({"frames":1})J");
        const PostProcess& p = *e.GetScene().Get<PostProcess>(camera);
        const bool hdr = mode == 2 || mode == 3 || mode == 6;
        CHECK(p.exposure == (hdr ? 0.75f : 1) && p.toneMapping == (hdr ? "reinhard" : "none"));
        CHECK((p.bloom > 0) == (mode == 3 || mode == 6));
        CHECK((p.vignette > 0) == (mode == 4 || mode == 6));
        CHECK(p.fxaa == (mode == 5 || mode == 6));
        CHECK(e.Call("input.key", Json::parse("{\"key\":\"" + key + "\",\"down\":false}"))["ok"].asBool());
        Call(e, "sim.step", R"J({"frames":1})J");
    }
    CHECK(e.GetScene().Get<UIText>(e.GetScene().FindByName("Hint"))->text.find("All: Off") != std::string::npos);
    CHECK(e.Scripts().Errors().empty());
}

TEST(ShaderGraphSceneUniforms) {
    // cameraPosition and lightDirection are reserved uniform names filled by the renderer,
    // so a view-dependent graph follows a moving camera without material edits.
    Engine e;
    std::string error;
    CHECK(e.Open(TempProject("shader_scene_uniforms"), &error));
    Call(e, "scene.new", R"J({"empty":true})J");
    CHECK(Call(e, "shader.create", R"J({"path":"materials/side.shader.json","graph":{
      "uniforms":{"cameraPosition":[9,9,9,9],"lightDirection":[9,9,9,9]},
      "nodes":[{"op":"uniform","name":"cameraPosition"},{"op":"uniform","name":"lightDirection"},
      {"op":"constant","value":0},{"op":"step","args":[2,0]},{"op":"swizzle","args":[3],"value":[0,0,0,0]},
      {"op":"constant","value":[1,0,0,1]},{"op":"constant","value":[0,0,1,1]},
      {"op":"mix","args":[5,6,4]}],"color":7}})J")["ok"].asBool());
    CHECK(Call(e, "material.create", R"J({"path":"side.mat.json","values":{"unlit":true,
      "shader":"materials/side.shader.json","shaderUniforms":{"cameraPosition":[-50,0,0,1]}}})J")["ok"].asBool());
    Call(e, "entity.create", R"J({"name":"Camera","components":{"Transform":{"position":[3,0,10]},"Camera":{"clearColor":[0,0,0]}}})J");
    Call(e, "entity.create", R"J({"name":"Sun","components":{"Transform":{"rotation":[-40,25,0]},"DirectionalLight":{}}})J");
    Call(e, "entity.create", R"J({"name":"Cube","components":{"Transform":{"scale":[4,4,1]},"MeshRenderer":{"material":"side.mat.json"}}})J");
    auto count = [&](uint32_t rgb) {
        RenderTarget target; target.Resize(128, 72);
        e.RenderGameView(target);
        int n = 0;
        for (uint32_t color : target.color) n += (color & 0xFFFFFF) == rgb;
        return n;
    };
    CHECK(count(0xFF0000) > 100 && count(0x0000FF) == 0);  // camera at +X: blue, despite the override
    Call(e, "component.set", R"J({"id":"Camera","type":"Transform","values":{"position":[-3,0,10]}})J");
    CHECK(count(0x0000FF) > 100 && count(0xFF0000) == 0);  // camera at -X: red
    RenderView view = MakeLookAtView(Vec3(1,2,3), Vec3(0,0,0), 45, 1);
    auto items = GatherRenderItems(e.GetScene(), &e.Assets(), view.view);
    RenderLights lights = GatherRenderLights(e.GetScene());
    auto draws = BuildDrawList(items, view.eye, &lights);
    CHECK(draws.size() == 1 && draws[0].material.shader);
    if (draws.size() != 1 || !draws[0].material.shader) return;
    const Vec4 eye = draws[0].material.shaderUniforms[0], light = draws[0].material.shaderUniforms[1];
    CHECK(eye.x == 1 && eye.y == 2 && eye.z == 3 && eye.w == 1);
    const Vec3 toward = -Normalize(lights.dirs[0].dir);
    CHECK(Length(light.xyz() - toward) < 1e-6f && light.w == 0 && toward.y > 0.5f);
    draws = BuildDrawList(items, view.eye);  // no lights supplied: the declared value stays
    CHECK(draws[0].material.shaderUniforms[1].x == 9);

    // `playing` is 1 while the game is played and 0 while its scene is edited, whatever the graph
    // and the material say: an effect that is in the way while editing switches itself off.
    CHECK(Call(e, "shader.create", R"J({"path":"materials/played.shader.json","graph":{
      "uniforms":{"playing":[1,1,1,1]},
      "nodes":[{"op":"uniform","name":"playing"},{"op":"constant","value":[0,0,1,1]},{"op":"constant","value":[1,0,0,1]},
      {"op":"mix","args":[1,2,0]}],"color":3}})J")["ok"].asBool());
    CHECK(Call(e, "material.create", R"J({"path":"played.mat.json","values":{"unlit":true,
      "shader":"materials/played.shader.json","shaderUniforms":{"playing":1}}})J")["ok"].asBool());
    Call(e, "component.set", R"J({"id":"Cube","type":"MeshRenderer","values":{"material":"played.mat.json"}})J");
    CHECK(!e.InPlaySession() && count(0xFF0000) > 100 && count(0x0000FF) == 0);  // edited: 0, despite default and override
    Call(e, "sim.step", R"J({"frames":1})J");
    CHECK(e.InPlaySession() && count(0x0000FF) > 100 && count(0xFF0000) == 0);   // played: 1
    Call(e, "sim.stop");
    CHECK(count(0xFF0000) > 100 && count(0x0000FF) == 0);
    items = GatherRenderItems(e.GetScene(), &e.Assets(), view.view);
    CHECK(BuildDrawList(items, view.eye, nullptr, true)[0].material.shaderUniforms[0].x == 1);
    CHECK(BuildDrawList(items, view.eye)[0].material.shaderUniforms[0].x == 0);
}

TEST(UIQuadsAreWhatSoftwareDraws) {
    // Both renderers draw UI from BuildUIQuads; the software result is the reference.
    Engine e;
    std::string err;
    CHECK(e.Open(TestSourceDir() + "/tests/fixtures/Showcase", &err));
    std::vector<UIQuad> quads = BuildUIQuads(e.GetScene(), 640, 360, &e.Assets());
    CHECK(quads.size() > 50);  // one textured quad per glyph
    RenderTarget rt;
    rt.Resize(640, 360);
    e.RenderGameView(rt);
    std::set<EntityId> drawn;
    for (const UIQuad& q : quads) {
        CHECK(q.x1 > q.x0 && q.y1 > q.y0);
        CHECK(q.texture != nullptr);  // Showcase UI is all text in the default font
        for (int y = std::max(0, q.y0); y < std::min(360, q.y1); ++y) {
            for (int x = std::max(0, q.x0); x < std::min(640, q.x1); ++x) {
                Color c;
                float a;
                ShadeUIQuad(q, x + 0.5f, y + 0.5f, &c, &a);
                if (a >= 0.5f * q.alpha && rt.IdAt(x, y) == q.entity) drawn.insert(q.entity);
            }
        }
    }
    for (const auto& kv : e.GetScene().Pool<UIText>()) CHECK(!kv.second.visible || drawn.count(kv.first));
}

TEST(UITextFontsAndRichText) {
    // UTF-8 decoding and the embedded default font.
    std::vector<uint32_t> cps = DecodeUtf8("A\xea\xb0\x80\xff");
    CHECK(cps.size() == 3 && cps[0] == 'A' && cps[1] == 0xAC00 && cps[2] == 0xFFFD);
    std::shared_ptr<FontFace> roboto = FontFace::Default();
    CHECK(roboto && roboto->familyName == "Roboto" && roboto->HasGlyph('g') && !roboto->HasGlyph(0xAC00));
    FontFace::Glyph g = roboto->GetGlyph('H', 32, false);
    CHECK(g.page == 0 && g.w > 10 && g.h > 18 && g.y0 < 0 && g.advance > 15.0f);
    CHECK(roboto->GetGlyph('H', 32, true).w > g.w);  // synthetic bold is wider
    float w1, h1, w2, h2, wp, hp;
    MeasureText("Hello", 32, &w1, &h1, "default");
    MeasureText("Hello\nWorld", 32, &w2, &h2, "default");
    MeasureText("Hello", 32, &wp, &hp, "pixel");
    CHECK(w1 > 60 && w1 < 90 && std::fabs(w2 - w1) < 20 && h2 > h1 * 1.8f);
    CHECK(wp == (5 * 6 - 1) * 4.0f && hp == 7 * 4.0f);  // pixel font: 6x8 cells of 4 px

    Engine e;
    std::string err;
    CHECK(e.Open(TempProject("ui_text"), &err));
    e.Call("scene.new", Json::parse(R"J({"empty": true})J"));
    // A font file in the project (the embedded Roboto written out).
    CreateDirectories(JoinPath(e.ProjectDir(), "assets/fonts"));
    CHECK(CopyFileTo(TestSourceDir() + "/third_party/fonts/Roboto-Regular.ttf", JoinPath(e.ProjectDir(), "assets/fonts/body.ttf")));
    Json info = Call(e, "asset.info", R"J({"path": "assets/fonts/body.ttf"})J")["result"];
    CHECK(info["kind"].asString() == "font" && info["family"].asString() == "Roboto");
    Call(e, "entity.create", R"J({"name": "Red", "components": {"UIText": {"text": "<color=#ff0000>WW</color>WW", "font": "assets/fonts/body.ttf", "x": 0, "y": 0, "size": 72}}})J");
    Call(e, "entity.create", R"J({"name": "Raw", "components": {"UIText": {"text": "<b>", "richText": false, "x": 0, "y": 200, "size": 40}}})J");
    Call(e, "entity.create", R"J({"name": "Wrapped", "components": {"UIText": {"text": "one two three four five six", "x": 0, "y": 400, "width": 120, "size": 24}}})J");
    Call(e, "entity.create", R"J({"name": "Typed", "components": {"UIText": {"text": "abc", "x": 600, "y": 0, "visibleCharacters": 0}}})J");
    RenderTarget rt;
    rt.Resize(1280, 720);
    RenderView view;
    MakeSceneView(e.GetScene(), 1280.0f / 720.0f, view);
    e.Renderer().Render(e.GetScene(), view, rt);
    int red = 0, white = 0;
    EntityId redId = e.GetScene().FindByName("Red");
    for (int y = 0; y < 100; ++y) {
        for (int x = 0; x < 400; ++x) {
            uint32_t c = rt.color[static_cast<size_t>(y) * 1280 + static_cast<size_t>(x)];
            if (rt.IdAt(x, y) != redId) continue;
            if ((c & 0xFF) > 200 && ((c >> 8) & 0xFF) < 60) ++red;
            if ((c & 0xFF) > 200 && ((c >> 8) & 0xFF) > 200) ++white;
        }
    }
    CHECK(red > 200 && white > 200);
    Json layout = Call(e, "ui.layout", R"J({"width": 1280, "height": 720})J")["result"]["elements"];
    CHECK(layout.size() == 4);
    CHECK(layout[1]["rect"][2].asNumber() > 40);   // "<b>" drawn literally: three glyphs
    CHECK(layout[2]["rect"][2].asNumber() == 120);  // the box width
    CHECK(layout[2]["rect"][3].asNumber() > 70);    // wrapped onto 3 lines
    for (const UIQuad& q : BuildUIQuads(e.GetScene(), 1280, 720, &e.Assets())) CHECK(q.entity != e.GetScene().FindByName("Typed"));
}

TEST(UILayoutAnchorsAndClipping) {
    Engine e;
    std::string err;
    CHECK(e.Open(TempProject("ui_layout"), &err));
    e.Call("scene.new", Json::parse(R"J({"empty": true})J"));
    // A fitted vertical menu: padding 10, spacing 5, children 100x40 and 120x30.
    Call(e, "entity.create", R"J({"name": "Menu", "components": {"UIPanel": {"anchor": "top-left", "x": 100, "y": 50, "width": 0, "height": 0}, "UILayout": {"direction": "vertical", "padding": 10, "spacing": 5, "fit": true}}})J");
    Call(e, "entity.create", R"J({"name": "A", "parent": "Menu", "components": {"UIButton": {"width": 100, "height": 40}}})J");
    Call(e, "entity.create", R"J({"name": "B", "parent": "Menu", "components": {"UIButton": {"width": 120, "height": 30, "order": -5}}})J");
    // Stretch inside a clipping panel; a child outside the clip cannot be clicked.
    Call(e, "entity.create", R"J({"name": "Frame", "components": {"UIPanel": {"anchor": "bottom-right", "x": -20, "y": -20, "width": 200, "height": 100, "clip": true}}})J");
    Call(e, "entity.create", R"J({"name": "Fill", "parent": "Frame", "components": {"UIImage": {"anchor": "stretch", "width": -20, "height": -20}}})J");
    Call(e, "entity.create", R"J({"name": "Hidden", "parent": "Frame", "components": {"UIButton": {"anchor": "top-left", "x": 150, "y": 0, "width": 100, "height": 50}}})J");
    Json els = Call(e, "ui.layout", R"J({"width": 1280, "height": 720})J")["result"]["elements"];
    std::map<std::string, Json> by;
    for (const Json& j : els.items()) by[j["name"].asString()] = j["rect"];
    auto rect = [&](const char* n, double x, double y, double w, double h) {
        const Json& r = by[n];
        return std::fabs(r[0].asNumber() - x) < 0.01 && std::fabs(r[1].asNumber() - y) < 0.01 && std::fabs(r[2].asNumber() - w) < 0.01 && std::fabs(r[3].asNumber() - h) < 0.01;
    };
    CHECK(rect("Menu", 100, 50, 140, 95));
    CHECK(rect("A", 110, 60, 100, 40));  // hierarchy order: A first although B has a lower draw order
    CHECK(rect("B", 110, 105, 120, 30));
    CHECK(rect("Frame", 1060, 600, 200, 100));
    CHECK(rect("Fill", 1070, 610, 180, 80));
    CHECK(Call(e, "input.click", R"J({"x": 1270, "y": 620, "width": 1280, "height": 720})J")["result"]["button"].asInt() == 0);  // clipped part
    CHECK(Call(e, "input.click", R"J({"x": 1220, "y": 620, "width": 1280, "height": 720})J")["result"]["buttonName"].asString() == "Hidden");
    // Horizontal row, centered, and a grid.
    Call(e, "component.set", R"J({"id": "Menu", "type": "UILayout", "values": {"direction": "horizontal", "crossAlign": "center"}})J");
    els = Call(e, "ui.layout", R"J({"width": 1280, "height": 720})J")["result"]["elements"];
    for (const Json& j : els.items()) by[j["name"].asString()] = j["rect"];
    CHECK(rect("Menu", 100, 50, 245, 60));
    CHECK(rect("B", 215, 65, 120, 30));
    // UICanvas: author for 1920x1080, match width.
    Call(e, "entity.create", R"J({"name": "Canvas", "components": {"UICanvas": {"referenceWidth": 1920, "referenceHeight": 1080, "match": 0}}})J");
    CHECK(std::fabs(Call(e, "ui.layout", R"J({"width": 960, "height": 720})J")["result"]["scale"].asNumber() - 0.5) < 1e-6);
}

TEST(UIInteractionHoverSliderAndDisabled) {
    Engine e;
    std::string err;
    CHECK(e.Open(TempProject("ui_input"), &err));
    e.Call("scene.new", Json::parse(R"J({"empty": true})J"));
    Call(e, "script.write", R"J({"path": "scripts/ui_log.lua", "source": "local M = {}
log_ = log_ or {}
function M:onPointerEnter() table.insert(log_, 'enter') end
function M:onPointerExit() table.insert(log_, 'exit') end
function M:onClick() table.insert(log_, 'click') end
function M:onValueChanged(v) table.insert(log_, string.format('value %.2f', v)) end
return M
"})J");
    Call(e, "entity.create", R"J({"name": "Btn", "components": {"UIButton": {"anchor": "top-left", "x": 0, "y": 0, "width": 200, "height": 100}, "Script": {"path": "scripts/ui_log.lua"}}})J");
    Call(e, "entity.create", R"J({"name": "Off", "components": {"UIButton": {"anchor": "top-left", "x": 300, "y": 0, "width": 200, "height": 100, "interactable": false}, "Script": {"path": "scripts/ui_log.lua"}}})J");
    Call(e, "entity.create", R"J({"name": "Vol", "components": {"UISlider": {"anchor": "top-left", "x": 0, "y": 200, "width": 400, "height": 40, "value": 0, "step": 0.25}, "Script": {"path": "scripts/ui_log.lua"}}})J");
    auto logText = [&] {
        return Call(e, "script.eval", R"J({"code": "table.concat(log_ or {}, ',')"})J")["result"]["value"].asString();
    };
    Call(e, "input.mouse", R"J({"x": 100, "y": 50, "width": 1280, "height": 720})J");
    Call(e, "sim.step", R"J({"frames": 1})J");
    CHECK(e.GetScene().Get<UIButton>(e.GetScene().FindByName("Btn"))->hovered);
    Call(e, "input.mouse", R"J({"x": 400, "y": 50, "width": 1280, "height": 720, "button": "MouseLeft", "down": true})J");
    Call(e, "sim.step", R"J({"frames": 1})J");
    Call(e, "input.mouse", R"J({"button": "MouseLeft", "down": false})J");
    Call(e, "sim.step", R"J({"frames": 1})J");
    CHECK(logText() == "enter,exit");  // the disabled button neither hovers nor clicks
    // Press on the slider at 60 % and drag past its end: snapped values, callback per change.
    Call(e, "input.mouse", R"J({"x": 240, "y": 220, "width": 1280, "height": 720, "button": "MouseLeft", "down": true})J");
    Call(e, "sim.step", R"J({"frames": 1})J");
    Call(e, "input.mouse", R"J({"x": 900, "y": 500, "width": 1280, "height": 720})J");
    Call(e, "sim.step", R"J({"frames": 1})J");
    CHECK(e.GetScene().Get<UISlider>(e.GetScene().FindByName("Vol"))->value == 1.0f);
    Call(e, "input.mouse", R"J({"button": "MouseLeft", "down": false})J");
    Call(e, "sim.step", R"J({"frames": 1})J");
    CHECK(logText() == "enter,exit,enter,value 0.50,exit,value 1.00");
    Call(e, "input.click", R"J({"x": 100, "y": 50, "width": 1280, "height": 720})J");
    Call(e, "sim.step", R"J({"frames": 1})J");
    CHECK(logText() == "enter,exit,enter,value 0.50,exit,value 1.00,enter,click");
    CHECK(e.Scripts().Errors().empty());
    Call(e, "sim.stop", "{}");
    CHECK(e.GetScene().Get<UISlider>(e.GetScene().FindByName("Vol"))->value == 0.0f);
}

// Mean color of a pixel block in a rendered target.
Color MeanColor(const RenderTarget& rt, int x0, int y0, int x1, int y1) {
    double r = 0, g = 0, b = 0;
    int n = 0;
    for (int y = y0; y < y1; ++y) {
        for (int x = x0; x < x1; ++x) {
            uint32_t c = rt.color[static_cast<size_t>(y) * static_cast<size_t>(rt.width) + static_cast<size_t>(x)];
            r += c & 0xFF;
            g += (c >> 8) & 0xFF;
            b += (c >> 16) & 0xFF;
            ++n;
        }
    }
    return Color(static_cast<float>(r / n / 255), static_cast<float>(g / n / 255), static_cast<float>(b / n / 255));
}

