// Binary Json payloads: exact round trip, compact repeated keys, and hostile input is rejected
// without large allocations.
TEST(NetworkJsonCodecRoundTripAndBounds) {
    Json world = Json::MakeObject();
    for (int i = 1; i <= 200; ++i) {
        Json entity = Json::parse(R"({"name":"Player","owner":3,"predict":true,"prefab":"prefabs/player.prefab.json","always":[],"Transform.position":[1.5,-2.25,1000000],"Transform.rotation":[0,90,0],"Tag.tags":"a"})");
        entity["source"] = i; entity["Transform.position"][0] = 0.1 * i; world[std::to_string(i)] = entity;
    }
    world["misc"] = Json::parse(R"([null,true,false,-7,9007199254740991,0.1,1e300,"",{"nested":{"deep":[1,2,3]}}])");
    std::vector<uint8_t> bytes; CHECK(EncodeJson(world, bytes, 56000));
    Json decoded; CHECK(DecodeJson(bytes.data(), bytes.size(), decoded)); CHECK(decoded == world && decoded.dump() == world.dump());
    CHECK(bytes.size() * 3 < world.dump().size());  // interned keys and binary numbers
    std::vector<uint8_t> small; CHECK(!EncodeJson(world, small, 100) && small.empty());
    Json deep = Json::MakeArray(), nan = Json::MakeArray(); nan.push(std::nan(""));
    for (int i = 0; i < 20; ++i) { Json outer = Json::MakeArray(); outer.push(deep); deep = outer; }
    CHECK(!EncodeJson(deep, small, 56000) && !EncodeJson(nan, small, 56000));
    Json out = Json("unchanged");
    // Truncation at every length, trailing bytes, unknown tags and absurd counts.
    for (size_t size = 0; size < bytes.size(); size += 7) CHECK(!DecodeJson(bytes.data(), size, out));
    std::vector<uint8_t> trailing = bytes; trailing.push_back(0); CHECK(!DecodeJson(trailing.data(), trailing.size(), out));
    for (std::vector<uint8_t> bad : {std::vector<uint8_t>{11}, {9, 0xff, 0xff, 0xff, 0xff, 0x0f}, {10, 0xff, 0xff, 0xff, 0x7f},
                                     {8, 0}, {7, 5, 'a'}, {3, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0x7f},
                                     {5, 0, 0, 0x80, 0x7f}, {6, 0, 0, 0, 0, 0, 0, 0xf0, 0x7f}})
        CHECK(!DecodeJson(bad.data(), bad.size(), out));
    std::vector<uint8_t> nested(40, 9); for (size_t i = 0; i < nested.size(); ++i) nested[i] = i % 2 ? 1 : 9;
    CHECK(!DecodeJson(nested.data(), nested.size(), out));
    CHECK(out == Json("unchanged"));
    uint32_t seed = 12345;
    for (int round = 0; round < 2000; ++round) {
        std::vector<uint8_t> fuzz = bytes;
        for (int flips = 0; flips < 4; ++flips) { seed = seed * 1664525u + 1013904223u; fuzz[(seed >> 8) % fuzz.size()] = static_cast<uint8_t>(seed >> 24); }
        Json ignored; DecodeJson(fuzz.data(), fuzz.size(), ignored);
    }
}

// Snapshots and their ACKs travel on the unreliable channel: a lossy link neither stalls the
// match behind retransmissions nor fills the reliable queue, and the client still converges.
TEST(NetworkAuthoritativeUnreliableSnapshotsConverge) {
    LoopbackConfig faults; faults.seed=977; faults.lossPermille=150; faults.duplicatePermille=80; faults.latencyFrames=1; faults.reorderFrames=3;
    auto wire=std::make_shared<LoopbackNetwork>(faults); SessionConfig config; config.mode="authoritative"; config.transport="loopback"; config.sync.keys={"W"};
    Session server(config,std::make_unique<LoopbackTransport>(wire,1),true,1,"Server",71,SessionTestRandom(830));
    Session client(config,std::make_unique<LoopbackTransport>(wire,2),false,1,"Client",0,SessionTestRandom(831));
    uint64_t tick=0; for(;tick<300;++tick) {server.Advance(tick);client.Advance(tick);}
    CHECK(server.Connected() && client.Connected());
    Authority host(config,true,1,99,[&](uint32_t player,const std::vector<uint8_t>& b){return server.SendSync(player,b);});
    Authority guest(config,false,2,99,[&](uint32_t player,const std::vector<uint8_t>& b){return client.SendSync(player,b);});
    uint64_t lossy=0;
    host.SetUnreliableSend([&](uint32_t player,const std::vector<uint8_t>& b){++lossy;return server.SendSync(player,b,false);});
    guest.SetUnreliableSend([&](uint32_t player,const std::vector<uint8_t>& b){return client.SendSync(player,b,false);});
    std::string error; CHECK(host.Start({1,2},&error)); uint64_t total=0,frames=0,received=0; Json last, world;
    auto pump=[&] {
        server.Advance(tick);client.Advance(tick);
        for(const auto& msg:server.DrainSync()) host.Receive(msg.first,msg.second);
        for(const auto& msg:client.DrainSync()) guest.Receive(msg.first,msg.second);
        host.TakeStart();guest.TakeStart();
        for(const auto& update:guest.DrainUpdates()) {last=update.world;++received;}
    };
    for(;tick<100000 && frames<5000;++tick) {
        pump();
        if(guest.Running() && guest.CanPredict()) {FrameInput input;input.down=(tick/7)%2;guest.Submit(input);}
        if(host.Running()) {
            auto inputs=host.Consume(FrameInput{});total+=inputs[2].down; ++frames;
            if(frames%3==0) {world=Json::MakeObject();world["1"]=Json::MakeObject();world["1"]["Transform.position"]=Json::parse("[0,0,0]");world["1"]["Transform.position"][0]=total;host.Snapshot(frames,{{2,world}});}
        }
        if(!host.Running() && frames) break;
    }
    CHECK(frames==5000 && host.Running() && guest.Running() && host.TakeDropped().empty());
    CHECK(lossy>1500 && received>800 && received<lossy);  // some snapshots were lost and never resent
    for(int n=0;n<300;++n,++tick) { if(n%3==0) host.Snapshot(frames,{{2,world}}); pump(); }
    CHECK(last==world);
    CHECK(server.Stats()["peers"][0]["pending"].asNumber()<32);
}

// dropPolicy "empty": after one timeout a stalled peer no longer costs a wait per frame, and a
// peer that resumes catches up through the buffered confirmed frames and plays again.
TEST(NetworkFrameSyncStalledPeerCatchesUp) {
    SyncConfig config; config.keys={"W"}; config.delay=2; config.waitFrames=30; config.emptyOnTimeout=true; config.hashInterval=600;
    std::deque<std::vector<uint8_t>> toClient, toHost;
    FrameSync host(config,true,1,5,[&](uint32_t,const std::vector<uint8_t>& b){toClient.push_back(b);return true;});
    FrameSync client(config,false,2,5,[&](uint32_t,const std::vector<uint8_t>& b){toHost.push_back(b);return true;});
    std::string error; CHECK(host.Start({1,2},&error));
    uint64_t tick=0, hostTotal=0, clientTotal=0; bool frozen=false; uint64_t clientPlayed=0;
    auto step=[&](FrameSync& sync, uint64_t& total, bool held, int frames) {
        sync.Tick(tick); sync.TakeStart();
        for(int n=0;n<frames;++n) {
            if(n && !sync.Lagging()) break;
            if(sync.NeedsInput()) {FrameInput input; input.down=held?1:0; sync.Submit(input);}
            sync.Tick(tick);
            auto inputs=sync.Next(); if(!inputs) break;
            for(const auto& input:*inputs) { total+=input.first*(input.second.down+1)+sync.Frame(); if(&sync==&host && input.first==2) clientPlayed+=input.second.down; }
            sync.Applied(*inputs);
        }
    };
    auto run=[&](uint64_t until) {
        for(;tick<until;++tick) {
            // One tick of latency each way; a frozen client neither reads nor simulates.
            auto in=std::move(toHost); toHost.clear(); for(const auto& b:in) host.Receive(2,b);
            step(host,hostTotal,false,1);
            if(!frozen) { auto out=std::move(toClient); toClient.clear(); for(const auto& b:out) client.Receive(1,b); step(client,clientTotal,true,1+FrameSync::kCatchUpFrames); }
        }
    };
    run(100); CHECK(host.Running() && client.Running() && host.Frame()>80 && clientPlayed>70);
    frozen=true; uint64_t before=host.Frame(); run(400);
    // One 30-tick wait, then full speed (the old behaviour gave about ten frames here).
    CHECK(host.Frame()>before+250 && host.State()["stalled"].size()==1);
    frozen=false; uint64_t played=clientPlayed; run(700);
    CHECK(host.Running() && client.Running() && host.State()["stalled"].size()==0);
    CHECK(client.Frame()+8>=host.Frame() && clientPlayed>played+150);
    // Both sides simulated the same merged inputs for every frame the client has reached.
    uint64_t target=client.Frame(); CHECK(target>600);
    frozen=true; CHECK(host.Frame()>=target);
    CHECK(client.State()["state"].asString()=="running" && client.State()["error"].asString().empty());
}

// The local API server runs on the platform sockets: request/response, a silent client cannot
// block Stop, and an ephemeral port is reported.
TEST(HttpServerOnPlatformSockets) {
#ifndef __EMSCRIPTEN__
    const uint64_t live = PlatformNetSocketsLive();
    {
        HttpServer server; std::string error, response;
        CHECK(server.Start(0, [](const HttpRequest& request) {
            HttpResponse out; out.body = request.method + " " + request.path + " " + request.Query("x") + " " + std::to_string(request.body.size());
            return out;
        }, &error));
        CHECK(server.Port() > 0);
        std::string large(300000, 'a');
        CHECK(HttpPostLocal(server.Port(), "/api/call?x=7", large, response, &error));
        CHECK(response == "POST /api/call 7 300000");
        for (int i = 0; i < 20; ++i) CHECK(HttpPostLocal(server.Port(), "/p", "{}", response, &error) && response == "POST /p  2");
        // A client that connects and never sends must not keep the server from stopping.
        auto silent = CreateNetSocket(SocketKind::Tcp, &error); CHECK(silent && silent->Connect({"127.0.0.1", static_cast<uint16_t>(server.Port())}, &error));
        PlatformSleep(0.05);
        const double start = PlatformTimeSeconds(); server.Stop(); CHECK(PlatformTimeSeconds() - start < 2.0);
        CHECK(!HttpPostLocal(server.Port(), "/p", "{}", response, &error) && !error.empty());
    }
    CHECK(PlatformNetSocketsLive() == live);
#endif
}

TEST(HostBridgeAndViewSize) {
    // host.call / host.poll: a game asks the embedding app for ads or purchases and reads its answer;
    // input.viewSize: the game view, which starts at the project's window size in headless sessions.
    const std::string dir = TempProject("host_bridge");
    std::string text;
    CHECK(ReadTextFile(dir + "/project.json", text));
    Json project = Json::parse(text);
    project["window"]["width"] = 540;
    project["window"]["height"] = 960;
    CHECK(WriteTextFile(dir + "/project.json", project.dump(2)));
    Engine e;
    std::string error;
    CHECK(e.Open(dir, &error));
    auto eval = [&](const std::string& code) {
        Json args = Json::MakeObject();
        args["code"] = code;
        return e.Call("script.eval", args)["result"]["value"];
    };
    Json size = eval("local w, h = input.viewSize() return {w, h}");
    CHECK(size[0].asInt() == 540 && size[1].asInt() == 960);
    CHECK(Call(e, "input.mouse", R"J({"x":10,"y":10,"width":800,"height":600})J")["ok"].asBool());
    size = eval("local w, h = input.viewSize() return {w, h}");
    CHECK(size[0].asInt() == 800 && size[1].asInt() == 600);

    // No host: the call is recorded and reports unhandled, so the game uses its fallback.
    CHECK(!eval("return host.call('ads.rewarded', {placement = 'revive'})").asBool());
    CHECK(eval("return host.language()").asString() == "en");
    CHECK(eval("return #host.poll()").asInt() == 0);
    Json state = Call(e, "host.state", "{}")["result"];
    CHECK(state["calls"].size() == 1 && state["calls"][0]["name"].asString() == "ads.rewarded");
    CHECK(!state["calls"][0]["handled"].asBool() && state["calls"][0]["data"]["placement"].asString() == "revive");

    // A tool stands in for the host, then answers like an ad SDK would.
    CHECK(Call(e, "host.configure", R"J({"accept":["ads.rewarded"],"language":"ko"})J")["result"]["language"].asString() == "ko");
    CHECK(eval("return host.call('ads.rewarded')").asBool());
    CHECK(!eval("return host.call('iap.purchase', {product = 'x'})").asBool());
    CHECK(eval("return host.language()").asString() == "ko");
    CHECK(Call(e, "host.reply", R"J({"name":"ads.result","data":{"ok":true,"n":3}})J")["result"]["pending"].asInt() == 1);
    CHECK(!Call(e, "host.reply", R"J({"name":""})J")["ok"].asBool());
    CHECK(!Call(e, "host.configure", R"J({"accept":"all"})J")["ok"].asBool());
    Json got = eval("local m = host.poll() return {#m, m[1].name, m[1].data.ok, m[1].data.n, #host.poll()}");
    CHECK(got[0].asInt() == 1 && got[1].asString() == "ads.result" && got[2].asBool() && got[3].asInt() == 3 && got[4].asInt() == 0);

    // The platform handler is asked when no tool accepts the name; both queues are bounded.
    std::string seen;
    e.SetHostAccept({});
    e.SetHostHandler([&](const std::string& name, const std::string& json) {
        seen = name + " " + json;
        return name == "game.ready";
    });
    CHECK(eval("return host.call('game.ready', {version = 2})").asBool());
    CHECK(seen.find("game.ready") == 0 && seen.find("\"version\"") != std::string::npos);
    CHECK(!eval("return host.call('other')").asBool());
    for (int i = 0; i < 300; ++i) e.PushHostMessage("m", Json::MakeObject());
    CHECK(e.PendingHostMessages() == Engine::kMaxHostMessages);
    for (int i = 0; i < 100; ++i) e.HostCall("n", Json::MakeObject());
    CHECK(e.HostCalls().size() == Engine::kMaxHostCalls);

    // web/ files belong to the page, not to the game data.
    CHECK(WriteTextFile(dir + "/web/host.js", "window.OEHost = {};"));
    for (const std::string& file : GameFiles(dir)) CHECK(file.rfind("web/", 0) != 0);
    RemoveAll(dir);
}

TEST(RPGVillageGame) {
    // The HD-2D village in games/RPG: scripts check clean, the opening shot hands control over, the hero
    // walks over the terrain grid (not into houses or water), Q turns the camera and time of day drives
    // the sun, lamps and clock.
    Engine e;
    std::string error;
    const std::string project = TestSourceDir() + "/games/RPG";
    CHECK(e.Open(project, &error));
    for (const std::string& file : GameFiles(project)) {
        if (file.size() < 4 || file.substr(file.size() - 4) != ".lua") continue;
        Json args = Json::MakeObject();
        args["path"] = file;
        Json result = e.Call("script.check", args)["result"];
        CHECK(result["errors"].asInt() == 0 && result["warnings"].asInt() == 0);
    }
    auto step = [&](int frames) {
        Json args = Json::MakeObject();
        args["frames"] = frames;
        CHECK(e.Call("sim.step", args)["ok"].asBool());
    };
    auto eval = [&](const std::string& code) {
        Json args = Json::MakeObject();
        args["code"] = code;
        args["entity"] = "Game";
        return e.Call("script.eval", args)["result"]["value"];
    };
    auto key = [&](const char* name, bool down) {
        Json args = Json::MakeObject();
        args["key"] = name;
        args["down"] = down;
        CHECK(e.Call("input.key", args)["ok"].asBool());
    };
    const EntityId hero = e.GetScene().FindByName("Hero");
    const Vec3 start = e.GetScene().Get<Transform>(hero)->position;
    key("W", true);
    step(60);  // the opening shot keeps the hero still
    CHECK(Length(e.GetScene().Get<Transform>(hero)->position - start) < 1e-4f);
    CHECK(eval("return game.get('locked')").asBool());
    step(240);
    CHECK(!eval("return game.get('locked')").asBool());
    step(60);
    const Vec3 walked = e.GetScene().Get<Transform>(hero)->position;
    CHECK(walked.z < start.z - 1.0f);  // forward = away from the camera (-z at yaw 0)
    CHECK(e.GetScene().Get<Sprite>(hero)->frame / 4 == 2);  // back view row
    step(600);  // straight north ends at the house across the plaza or a terrace step, never inside it
    key("W", false);
    const Vec3 stopped = e.GetScene().Get<Transform>(hero)->position;
    CHECK(eval(std::string("return require('scripts.lib.terrain').height(") + std::to_string(static_cast<int>(std::floor(stopped.x + 0.5f))) +
               "," + std::to_string(static_cast<int>(std::floor(stopped.z + 0.5f))) + ")").asNumber() >= 0);
    key("Q", true);
    step(1);
    key("Q", false);
    step(60);
    CHECK(std::fabs(eval("return game.get('camYaw')").asNumber() - kPi / 4) < 0.02);
    // Billboards turn with the camera.
    CHECK(std::fabs(e.GetScene().Get<Transform>(e.GetScene().FindByName("Lamp1"))->rotation.y - 45.0f) < 1.5f);
    // Night: lamps on, windows glowing, fireflies; the clock says so.
    eval("self.tod = 0.85");
    step(60);
    const PointLight* lamp = e.GetScene().Get<PointLight>(e.GetScene().FindByName("Light"));
    CHECK(lamp && lamp->intensity > 1.5f);
    const MeshRenderer* windows = e.GetScene().Get<MeshRenderer>(e.GetScene().FindByName("Windows"));
    CHECK(windows && windows->shaderUniforms["glow"].asNumber() > 1.5);
    CHECK(e.GetScene().Get<UIText>(e.GetScene().FindByName("Clock"))->text.find("밤") == 0);
    eval("self.tod = 0.25");
    step(60);
    CHECK(e.GetScene().Get<PointLight>(e.GetScene().FindByName("Light"))->intensity < 0.1f);
    CHECK(Call(e, "script.errors", "{}")["result"].size() == 0);
}

TEST(NetworkAuthoritativeLateJoin) {
    // network.lateJoin: a dedicated server runs its world without players, admits whoever joins and
    // gets ready while it runs, keeps running when they leave, and takes them back.
    std::string project = AuthorityProject("authority_latejoin", "loopback", true), text, error;
    CHECK(ReadTextFile(JoinPath(project, "project.json"), text));
    Json config = Json::parse(text);
    config["network"]["lateJoin"] = true; config["network"]["maxPlayers"] = 4;
    CHECK(WriteTextFile(JoinPath(project, "project.json"), config.dump(2)));
    Engine server, a, b;
    for (Engine* e : {&server, &a, &b}) {
        CHECK(e->Open(project, &error)); e->GetScene().Clear();
        CHECK(Call(*e, "entity.create", R"({"name":"Remote","components":{"Transform":{},"Script":{"path":"scripts/drift.lua"},"NetSync":{"fields":{"Transform.position":{"onChange":true}}}}})")["ok"].asBool());
    }
    auto steps = [&](int count) { for (int i = 0; i < count; ++i) { server.Step(1); a.Step(1); b.Step(1); } };
    auto sync = [](Engine& e) { return e.NetworkCall("state", Json())["sync"]["state"].asString(); };
    auto avatar = [](Engine& e, int player) {
        for (const auto& kv : e.GetScene().Pool<NetPlayer>()) if (kv.second.player == player) return kv.first;
        return kNullEntity;
    };
    auto x = [](Engine& e, EntityId id) { const Transform* t = e.GetScene().Get<Transform>(id); return t ? t->position.x : -1.0f; };
    const char* join = R"({"address":"late-room"})";

    CHECK(Call(server, "net.serve", R"({"seed":71,"room":"late-room"})")["ok"].asBool());
    steps(60);
    CHECK(sync(server) == "running" && server.Frame() >= 50);  // the world started without anybody
    CHECK(server.GetScene().Pool<NetPlayer>().empty());

    // Joining alone is only the lobby: the player enters the world when it is ready.
    CHECK(Call(a, "net.join", join)["ok"].asBool()); steps(40);
    CHECK(a.NetworkCall("state", Json())["state"].asString() == "lobby" && sync(a) != "running");
    CHECK(server.GetScene().Pool<NetPlayer>().empty());
    CHECK(Call(a, "net.ready", R"({"ready":true})")["ok"].asBool()); steps(60);
    CHECK(sync(a) == "running" && sync(server) == "running");
    CHECK(server.GetScene().Pool<NetPlayer>().size() == 1 && avatar(server, 2) != kNullEntity && avatar(a, 2) != kNullEntity);
    CHECK(x(a, a.GetScene().FindByName("Remote")) > 1.5f);  // the world it entered is the server's, not a fresh one
    a.Input().down.insert("W"); steps(60);
    CHECK(x(server, avatar(server, 2)) > 30 && x(a, avatar(a, 2)) > 30);

    // A second player arrives much later; both see each other (the first one's roster predates it).
    CHECK(Call(b, "net.join", join)["ok"].asBool()); steps(30);
    CHECK(Call(b, "net.ready", R"({"ready":true})")["ok"].asBool()); steps(80);
    CHECK(sync(b) == "running" && sync(a) == "running");
    CHECK(server.GetScene().Pool<NetPlayer>().size() == 2 && a.GetScene().Pool<NetPlayer>().size() == 2 && b.GetScene().Pool<NetPlayer>().size() == 2);
    CHECK(avatar(a, 3) != kNullEntity && x(b, avatar(b, 2)) > 60);
    b.Input().down.insert("W"); steps(40);
    CHECK(x(server, avatar(server, 3)) > 15);

    // One leaves: its avatar goes, the other keeps playing. Then the last one: the server stays up.
    CHECK(Call(a, "net.leave")["ok"].asBool()); a.Input().down.clear(); steps(120);
    CHECK(server.GetScene().Pool<NetPlayer>().size() == 1 && b.GetScene().Pool<NetPlayer>().size() == 1 && sync(b) == "running");
    CHECK(Call(b, "net.leave")["ok"].asBool()); steps(200);
    CHECK(sync(server) == "running" && server.GetScene().Pool<NetPlayer>().empty());
    uint64_t frame = server.Frame(); steps(30); CHECK(server.Frame() == frame + 30);

    // And somebody comes back into the same world.
    CHECK(Call(a, "net.join", join)["ok"].asBool()); steps(30);
    CHECK(Call(a, "net.ready", R"({"ready":true})")["ok"].asBool()); steps(80);
    CHECK(sync(a) == "running" && a.GetScene().Pool<NetPlayer>().size() == 1 && server.GetScene().Pool<NetPlayer>().size() == 1);
    CHECK(x(a, a.GetScene().FindByName("Remote")) > 8.0f);
    for (Engine* e : {&server, &a, &b}) CHECK(e->Scripts().Errors().empty());

    // game.quit only raises a flag for the game runtime; stopping the session clears it.
    CHECK(!Call(b, "game.state")["result"]["quitRequested"].asBool());
    CHECK(Call(b, "game.quit")["ok"].asBool() && Call(b, "game.state")["result"]["quitRequested"].asBool());
    b.Stop(); CHECK(!Call(b, "game.state")["result"]["quitRequested"].asBool());
    server.Stop(); a.Stop(); RemoveAll(project);
}

TEST(NetworkAuthoritativeMatchInLoadedScene) {
    // A world per scene: a server started on a scene file other than the project's start scene, and a
    // client that got there with game.loadScene before it joined, begin from the same world. A client
    // still in the start scene is not let into it.
    std::string project = AuthorityProject("authority_scenes", "loopback", true), text, error;
    CHECK(ReadTextFile(JoinPath(project, "project.json"), text));
    Json config = Json::parse(text);
    config["network"]["lateJoin"] = true; config["network"]["maxPlayers"] = 4;
    CHECK(WriteTextFile(JoinPath(project, "project.json"), config.dump(2)));
    const std::string field = JoinPath(project, "scenes/field.scene.json");
    {
        Engine author; CHECK(author.Open(project, &error)); author.GetScene().Clear();
        CHECK(Call(author, "entity.create", R"({"name":"Field Thing","components":{"Transform":{},"Script":{"path":"scripts/drift.lua"},"NetSync":{"fields":{"Transform.position":{"onChange":true}}}}})")["ok"].asBool());
        CHECK(author.SaveScene(field, &error));
    }
    Engine server, a, b;
    CHECK(server.Open(field, &error)); CHECK(a.Open(project, &error)); CHECK(b.Open(project, &error));
    auto steps = [&](int count) { for (int i = 0; i < count; ++i) { server.Step(1); a.Step(1); b.Step(1); } };
    auto sync = [](Engine& e) { return e.NetworkCall("state", Json())["sync"]["state"].asString(); };
    const char* join = R"({"address":"scene-room"})";
    CHECK(Call(server, "net.serve", R"({"seed":5,"room":"scene-room"})")["ok"].asBool());
    steps(30);
    CHECK(sync(server) == "running" && server.GetScene().FindByName("Field Thing") != kNullEntity);

    CHECK(a.GetScene().FindByName("Field Thing") == kNullEntity);
    CHECK(Call(a, "sim.play")["ok"].asBool());
    CHECK(Call(a, "game.load_scene", R"({"path":"scenes/field.scene.json"})")["ok"].asBool()); steps(2);
    CHECK(Call(a, "game.state")["result"]["scene"].asString() == "scenes/field.scene.json");
    CHECK(Call(a, "net.join", join)["ok"].asBool()); steps(30);
    CHECK(Call(a, "net.ready", R"({"ready":true})")["ok"].asBool()); steps(80);
    CHECK(sync(a) == "running" && server.GetScene().Pool<NetPlayer>().size() == 1 && a.GetScene().Pool<NetPlayer>().size() == 1);
    const EntityId thing = a.GetScene().FindByName("Field Thing");
    CHECK(thing != kNullEntity && a.GetScene().Get<Transform>(thing)->position.x > 1.0f);  // the server's world, in the field
    CHECK(Call(a, "game.state")["result"]["scene"].asString() == "scenes/field.scene.json");

    // The start scene is another world: no match for a client that did not change scene.
    CHECK(Call(b, "net.join", join)["ok"].asBool()); steps(30);
    Call(b, "net.ready", R"({"ready":true})"); steps(80);
    CHECK(sync(b) != "running" && b.GetScene().FindByName("Field Thing") == kNullEntity);
    CHECK(sync(a) == "running" && sync(server) == "running");

    // Stopping the play session returns to the scene it started from, and forgets the loaded one.
    a.Stop(); CHECK(a.GetScene().FindByName("Field Thing") == kNullEntity);
    for (Engine* e : {&server, &a}) CHECK(e->Scripts().Errors().empty());
    server.Stop(); b.Stop(); RemoveAll(project);
}

TEST(DedicatedWorldsPerScene) {
    // One server, a world per scene: each scene is simulated by its own engine, all in one session,
    // stepped by one loop. A client's script may leave an authoritative match.
    std::string project = AuthorityProject("authority_worlds", "loopback", true), text, error;
    CHECK(ReadTextFile(JoinPath(project, "project.json"), text));
    Json config = Json::parse(text);
    config["network"]["lateJoin"] = true; config["network"]["maxPlayers"] = 4;
    CHECK(WriteTextFile(JoinPath(project, "project.json"), config.dump(2)));
    for (const char* name : {"town", "field"}) {
        Engine author; CHECK(author.Open(project, &error)); author.GetScene().Clear();
        Json created = Json::MakeObject(); created["name"] = std::string(name) + " thing"; created["components"]["Transform"] = Json::MakeObject();
        CHECK(author.Call("entity.create", created)["ok"].asBool());
        CHECK(author.SaveScene(JoinPath(project, std::string("scenes/") + name + ".scene.json"), &error));
    }
    CHECK(SplitSceneList("a.scene.json,,b.scene.json,") == (std::vector<std::string>{"a.scene.json", "b.scene.json"}));
    Json arguments = Json::MakeObject(); arguments["port"] = 41000; arguments["seed"] = 3; arguments["room"] = "worlds";
    std::vector<Json> started; std::vector<std::string> things; int prepared = 0;
    Json result = RunDedicatedWorlds(project, {"scenes/town.scene.json", "scenes/field.scene.json"}, arguments, 45,
        [&](Engine& world, std::string* failed) { ++prepared; return world.SetLaunchArg("channel", "7", failed); },
        [&](size_t, Engine& world, std::string*) {
            things.push_back(world.GetScene().FindByName("town thing") != kNullEntity ? "town thing" : world.GetScene().FindByName("field thing") != kNullEntity ? "field thing" : "?");
            return world.LaunchArgs().count("channel") && world.LaunchArgs().at("channel") == "7";
        },
        [&](const Json& envelope) { started.push_back(envelope); });
    CHECK(result["ok"].asBool() && prepared == 2);
    CHECK(things == (std::vector<std::string>{"town thing", "field thing"}));
    CHECK(started.size() == 2 && started[0]["world"].asInt(-1) == 0 && started[1]["world"].asInt(-1) == 1 &&
          started[1]["scene"].asString() == "scenes/field.scene.json");
    const Json& worlds = result["result"]["worlds"];
    CHECK(worlds.size() == 2 && result["result"]["ticks"].asInt(0) == 45);
    for (size_t i = 0; i < worlds.size(); ++i) {
        CHECK(worlds[i]["sync"]["state"].asString() == "running" && worlds[i]["frame"].asInt(0) >= 40);
        CHECK(worlds[i]["room"].asString() == "worlds" && worlds[i]["world"].asString() == worlds[i]["scene"].asString());  // one session
        CHECK(worlds[i]["worlds"].size() == 2);
    }
    CHECK(worlds[0]["scene"].asString() == "scenes/town.scene.json" && worlds[1]["scene"].asString() == "scenes/field.scene.json");
    // A scene that does not exist stops the run; so does the same scene twice (a world each).
    CHECK(!RunDedicatedWorlds(project, {"scenes/town.scene.json", "scenes/none.scene.json"}, arguments, 5)["ok"].asBool());
    CHECK(!RunDedicatedWorlds(project, {"scenes/town.scene.json", "scenes/town.scene.json"}, arguments, 5)["ok"].asBool());

    // A client leaves a running authoritative match from its own script; a host's script may not stop it.
    CHECK(WriteTextFile(JoinPath(project, "scripts/leaver.lua"), R"(
local M = {}
function M:onUpdate()
  local sync = net.state().sync
  if sync and sync.state == "running" and time.frame() == 60 then game.set("left", (pcall(net.leave))) end
end
return M
)"));
    Engine server, client;
    for (Engine* e : {&server, &client}) {
        std::string failed; CHECK(e->SetLaunchArg("leave", "1", &failed));
        CHECK(e->Open(project, &error)); e->GetScene().Clear();
        CHECK(Call(*e, "entity.create", R"({"name":"Leaver","components":{"Transform":{},"Script":{"path":"scripts/leaver.lua"}}})")["ok"].asBool());
    }
    auto steps = [&](int count) { for (int i = 0; i < count; ++i) { server.Step(1); client.Step(1); } };
    auto sync = [](Engine& e) { return e.NetworkCall("state", Json())["sync"]["state"].asString(); };
    CHECK(Call(server, "net.serve", R"({"seed":9,"room":"leave-room"})")["ok"].asBool()); steps(10);
    CHECK(Call(client, "net.join", R"({"address":"leave-room"})")["ok"].asBool()); steps(20);
    CHECK(Call(client, "net.ready", R"({"ready":true})")["ok"].asBool()); steps(20);
    CHECK(sync(client) == "running" && server.GetScene().Pool<NetPlayer>().size() == 1);
    steps(120);
    CHECK(Call(client, "game.state")["result"]["data"]["left"].asBool());
    CHECK(sync(client) != "running" && server.GetScene().Pool<NetPlayer>().empty());
    CHECK(sync(server) == "running" && !Call(server, "game.state")["result"]["data"]["left"].asBool());
    server.Stop(); client.Stop(); RemoveAll(project);
}

TEST(NetworkWorldsMovePlayers) {
    // One session, two worlds (a scene and an engine each). A player connects once, is in the first
    // world, and the server moves it to the other and back: its connection and player id stay, each
    // world sees it leave or join (with the data the other world gave), and RPC stays inside a world.
    std::string project = AuthorityProject("authority_move", "loopback", true), text, error;
    CHECK(ReadTextFile(JoinPath(project, "project.json"), text));
    Json config = Json::parse(text);
    config["network"]["lateJoin"] = true; config["network"]["maxPlayers"] = 4;
    CHECK(WriteTextFile(JoinPath(project, "project.json"), config.dump(2)));
    CHECK(WriteTextFile(JoinPath(project, "scripts/world.lua"), R"(
local M = {}
function M:onStart()
  net.on("ping", function(n) game.set("ping", n) end)
end
function M:onPlayerJoined(id, data) game.set("joined", id); game.set("data", data and data.hp or -1) end
function M:onPlayerLeft(id) game.set("left", id) end
return M
)"));
    const std::string town = "scenes/town.scene.json", field = "scenes/field.scene.json";
    for (const std::string& scene : {town, field}) {
        Engine author; CHECK(author.Open(project, &error)); author.GetScene().Clear();
        Json thing = Json::parse(R"({"components":{"Transform":{},"NetSync":{"fields":{"Transform.position":{"onChange":true}}}}})");
        thing["name"] = scene == town ? "Town Thing" : "Field Thing";
        CHECK(author.Call("entity.create", thing)["ok"].asBool());
        // The rules run on every peer (not replicated): each has its own copy from the scene.
        CHECK(Call(author, "entity.create", R"({"name":"Rules","components":{"Script":{"path":"scripts/world.lua"}}})")["ok"].asBool());
        CHECK(author.SaveScene(JoinPath(project, scene), &error));
    }
    Engine s0, s1, a, b;
    CHECK(s0.Open(JoinPath(project, town), &error)); CHECK(s1.Open(JoinPath(project, field), &error));
    CHECK(a.Open(project, &error)); CHECK(b.Open(project, &error));
    CHECK(Call(s0, "net.serve", R"({"seed":4,"room":"move-room"})")["ok"].asBool());
    CHECK(!s0.SharedNetwork()->SetWorlds({town, town}, &error));
    CHECK(s0.SharedNetwork()->SetWorlds({town, field}, &error));
    s1.ServeWorld(s0.SharedNetwork(), 1);
    auto steps = [&](int count) { for (int i = 0; i < count; ++i) { s0.Step(1); s1.Step(1); a.Step(1); b.Step(1); } };
    auto sync = [](Engine& e) { return e.NetworkCall("state", Json())["sync"]["state"].asString(); };
    auto scene = [](Engine& e) { return Call(e, "game.state")["result"]["scene"].asString(); };
    auto data = [](Engine& e, const char* key) { return Call(e, "game.state")["result"]["data"][key].asInt(-99); };
    auto avatars = [](Engine& e) { return e.GetScene().Pool<NetPlayer>().size(); };
    auto ids = [](Engine& e) { std::string out; const Json players = Call(e, "net.players")["result"]; for (const auto& p : players.items()) out += std::to_string(p["id"].asInt(0)) + " "; return out; };
    steps(30);
    CHECK(sync(s0) == "running" && sync(s1) == "running");
    CHECK(Call(s1, "net.state")["result"]["world"].asString() == field && Call(s0, "net.state")["result"]["worlds"].size() == 2);

    // Both players arrive in the first world (they loaded its scene before joining).
    for (Engine* e : {&a, &b}) {
        CHECK(Call(*e, "sim.play")["ok"].asBool());
        CHECK(Call(*e, "game.load_scene", R"({"path":"scenes/town.scene.json"})")["ok"].asBool());
    }
    steps(2);
    for (Engine* e : {&a, &b}) CHECK(Call(*e, "net.join", R"({"address":"move-room"})")["ok"].asBool());
    steps(30);
    for (Engine* e : {&a, &b}) CHECK(Call(*e, "net.ready", R"({"ready":true})")["ok"].asBool());
    steps(80);
    CHECK(sync(a) == "running" && sync(b) == "running" && avatars(s0) == 2 && avatars(s1) == 0 && avatars(a) == 2);
    CHECK(ids(s0) == "1 2 3 " && ids(s1) == "1 " && ids(a) == "1 2 3 ");

    // Player 2 goes to the field: only its own world may send it, and only to a world that exists.
    CHECK(!Call(s1, "net.move", R"({"player":2,"scene":"scenes/town.scene.json"})")["ok"].asBool());
    CHECK(!Call(s0, "net.move", R"({"player":2,"scene":"scenes/cave.scene.json"})")["ok"].asBool());
    CHECK(!Call(s0, "net.move", R"({"player":2,"scene":"scenes/town.scene.json"})")["ok"].asBool());
    CHECK(!Call(a, "net.move", R"({"player":2,"scene":"scenes/field.scene.json"})")["ok"].asBool());  // a client
    CHECK(Call(s0, "net.move", R"({"player":2,"scene":"scenes/field.scene.json","data":{"hp":7}})")["ok"].asBool());
    steps(120);
    CHECK(scene(a) == field && sync(a) == "running" && a.Network()->LocalPlayer() == 2 && a.Network()->Status() == "lobby");
    CHECK(a.GetScene().FindByName("Field Thing") != kNullEntity && a.GetScene().FindByName("Town Thing") == kNullEntity);
    CHECK(avatars(s0) == 1 && avatars(s1) == 1 && avatars(a) == 1 && avatars(b) == 1);
    CHECK(ids(s0) == "1 3 " && ids(s1) == "1 2 " && ids(a) == "1 2 " && ids(b) == "1 3 ");
    CHECK(data(s0, "left") == 2 && data(s1, "joined") == 2 && data(s1, "data") == 7);
    CHECK(sync(b) == "running" && scene(b) == town && sync(s0) == "running" && sync(s1) == "running");
    // Its avatar in the field is its own: it moves it there, and the town does not see it.
    for (const auto& kv : s1.GetScene().Pool<NetPlayer>()) CHECK(kv.second.player == 2);
    a.Input().down.insert("W"); steps(40); a.Input().down.clear();
    for (const auto& kv : s1.GetScene().Pool<NetPlayer>()) CHECK(s1.GetScene().Get<Transform>(kv.first)->position.x > 20);

    // RPC stays in a world: "all" from the town reaches the town's player only, a client's call its own world's server.
    CHECK(Call(s0, "net.rpc", R"({"target":"all","name":"ping","args":[1]})")["ok"].asBool());
    CHECK(Call(s1, "net.rpc", R"({"target":"all","name":"ping","args":[2]})")["ok"].asBool());
    steps(30);
    CHECK(data(a, "ping") == 2 && data(b, "ping") == 1);
    CHECK(Call(a, "net.rpc", R"({"name":"ping","args":[5]})")["ok"].asBool());
    CHECK(Call(b, "net.rpc", R"({"name":"ping","args":[6]})")["ok"].asBool());
    steps(30);
    CHECK(data(s1, "ping") == 5 && data(s0, "ping") == 6);
    CHECK(!Call(s0, "net.rpc", R"({"target":"2","name":"ping","args":[9]})")["ok"].asBool());  // not in the town any more

    // And back: the same player enters a world it has been in before.
    CHECK(Call(s1, "net.move", R"({"player":2,"scene":"scenes/town.scene.json"})")["ok"].asBool());
    steps(120);
    CHECK(scene(a) == town && sync(a) == "running" && avatars(s0) == 2 && avatars(s1) == 0 && avatars(a) == 2 && avatars(b) == 2);
    CHECK(ids(s0) == "1 2 3 " && data(s1, "left") == 2 && data(s0, "joined") == 2 && data(s0, "data") == -1);

    // A player that goes away is gone from the world it was in.
    CHECK(Call(s0, "net.move", R"({"player":3,"scene":"scenes/field.scene.json"})")["ok"].asBool());
    steps(120);
    CHECK(avatars(s1) == 1 && sync(b) == "running" && scene(b) == field);
    CHECK(Call(b, "net.leave")["ok"].asBool()); steps(120);
    CHECK(avatars(s1) == 0 && data(s1, "left") == 3 && ids(s1) == "1 " && sync(a) == "running" && avatars(s0) == 1);
    for (Engine* e : {&s0, &s1, &a, &b}) CHECK(e->Scripts().Errors().empty());
    s1.Stop(); s0.Stop(); a.Stop(); b.Stop(); RemoveAll(project);
}

TEST(NetworkScriptAdmission) {
    // network.admission "script": a ready lobby player enters the running world only after the game
    // called net.admit; the game may also kick from its own rules (a server checking a ticket).
    std::string project = AuthorityProject("authority_admission", "loopback", true), text, error;
    CHECK(ReadTextFile(JoinPath(project, "project.json"), text));
    Json config = Json::parse(text);
    config["network"]["maxPlayers"] = 4; config["network"]["admission"] = "script";
    CHECK(WriteTextFile(JoinPath(project, "project.json"), config.dump(2)));
    { Engine refused; CHECK(!refused.Open(project, &error) && error.find("lateJoin") != std::string::npos); }
    config["network"]["lateJoin"] = true;
    CHECK(WriteTextFile(JoinPath(project, "project.json"), config.dump(2)));
    CHECK(WriteTextFile(JoinPath(project, "scripts/gate.lua"), R"(
local M = {}
local seen = {}
function M:onUpdate()
  if not net.isServer() then return end
  for _, id in ipairs(net.players()) do
    if id ~= 1 and not seen[id] then
      seen[id] = true
      local name = net.name(id)
      if name == 'good' then net.admit(id) elseif name == 'bad' then net.kick({player = id, reason = 'no ticket'}) end
    end
  end
end
return M
)"));
    Engine server, good, bad, waiting;
    for (Engine* e : {&server, &good, &bad, &waiting}) {
        CHECK(e->Open(project, &error)); e->GetScene().Clear();
        CHECK(Call(*e, "entity.create", R"({"name":"Gate","components":{"Script":{"path":"scripts/gate.lua"}}})")["ok"].asBool());
    }
    auto steps = [&](int count) { for (int i = 0; i < count; ++i) { server.Step(1); good.Step(1); bad.Step(1); waiting.Step(1); } };
    auto sync = [](Engine& e) { return e.NetworkCall("state", Json())["sync"]["state"].asString(); };
    auto avatar = [](Engine& e, int player) {
        for (const auto& kv : e.GetScene().Pool<NetPlayer>()) if (kv.second.player == player) return kv.first;
        return kNullEntity;
    };
    CHECK(!Call(server, "net.serve", R"({"room":"gate-room","minPlayers":1})")["ok"].asBool());  // players only enter through net.admit
    CHECK(Call(server, "net.serve", R"({"seed":5,"room":"gate-room"})")["ok"].asBool());
    steps(30);
    CHECK(sync(server) == "running");

    // Nobody admitted it: ready, but it stays in the lobby without an avatar.
    CHECK(Call(waiting, "net.join", R"({"address":"gate-room","name":"somebody"})")["ok"].asBool()); steps(30);
    CHECK(Call(waiting, "net.ready", R"({"ready":true})")["ok"].asBool()); steps(90);
    CHECK(waiting.NetworkCall("state", Json())["state"].asString() == "lobby" && sync(waiting) != "running");
    CHECK(server.GetScene().Pool<NetPlayer>().empty());

    // The script admits "good" (before it is even ready) and kicks "bad".
    CHECK(Call(good, "net.join", R"({"address":"gate-room","name":"good"})")["ok"].asBool());
    CHECK(Call(bad, "net.join", R"({"address":"gate-room","name":"bad"})")["ok"].asBool()); steps(40);
    CHECK(server.GetScene().Pool<NetPlayer>().empty());  // admitted, not ready yet
    CHECK(Call(good, "net.ready", R"({"ready":true})")["ok"].asBool());
    if (bad.NetworkCall("state", Json())["state"].asString() == "lobby") Call(bad, "net.ready", R"({"ready":true})");
    steps(120);
    CHECK(sync(good) == "running" && server.GetScene().Pool<NetPlayer>().size() == 1 && avatar(server, 3) != kNullEntity);
    CHECK(bad.NetworkCall("state", Json())["state"].asString() != "lobby" && sync(bad) != "running");
    CHECK(sync(waiting) != "running" && avatar(server, 2) == kNullEntity);

    // Tools admit with the command; unknown players and clients are refused.
    CHECK(!Call(server, "net.admit", R"({"player":9})")["ok"].asBool());
    CHECK(!Call(good, "net.admit", R"({"player":2})")["ok"].asBool());
    CHECK(Call(server, "net.admit", R"({"player":2})")["ok"].asBool()); steps(90);
    CHECK(sync(waiting) == "running" && avatar(server, 2) != kNullEntity && server.GetScene().Pool<NetPlayer>().size() == 2);

    // An admission does not outlive the visit: the same player id is gone, a new one waits again.
    CHECK(Call(waiting, "net.leave")["ok"].asBool()); steps(120);
    CHECK(server.GetScene().Pool<NetPlayer>().size() == 1);
    CHECK(Call(waiting, "net.join", R"({"address":"gate-room","name":"somebody"})")["ok"].asBool()); steps(30);
    CHECK(Call(waiting, "net.ready", R"({"ready":true})")["ok"].asBool()); steps(90);
    CHECK(sync(waiting) != "running" && server.GetScene().Pool<NetPlayer>().size() == 1);
    for (Engine* e : {&server, &good, &waiting}) CHECK(e->Scripts().Errors().empty());
    for (Engine* e : {&server, &good, &bad, &waiting}) e->Stop();
    RemoveAll(project);
}

TEST(LinksAndLaunchArgs) {
    // link.*: framed TCP from a game to a service that is not an engine session (u32 length, u16 type,
    // payload); game.arg: launch parameters; a project's server/ folder is not game data.
    const std::string dir = TempProject("links");
    const uint64_t socketsLive = PlatformNetSocketsLive();
    std::string error;
    {
        Engine e;
        CHECK(e.Open(dir, &error));
        auto eval = [&](const std::string& code) {
            Json args = Json::MakeObject();
            args["code"] = code;
            return e.Call("script.eval", args)["result"]["value"];
        };

        // Launch parameters survive the play session; names and sizes are bounded.
        CHECK(Call(e, "game.args", R"({"set":{"channel":"2","map":"town"}})")["result"]["channel"].asString() == "2");
        CHECK(!Call(e, "game.args", R"({"set":{"bad name":"x"}})")["ok"].asBool());
        CHECK(WriteTextFile(dir + "/key.txt", "c0ffee\r\n"));
        CHECK(ApplyLaunchArg(e, "key=" + dir + "/key.txt", true, &error) && ApplyLaunchArg(e, "port=7001", false, &error));
        CHECK(!ApplyLaunchArg(e, "novalue", false, &error) && !ApplyLaunchArg(e, "key=" + dir + "/missing.txt", true, &error));
        e.Step(1);
        CHECK(eval("return game.arg('channel') .. game.arg('map') .. game.arg('key') .. game.arg('port')").asString() == "2townc0ffee7001");
        CHECK(eval("return game.arg('nothing') == nil").asBool());
        e.Stop(); e.Step(1);
        CHECK(eval("return game.arg('map')").asString() == "town");

#ifndef __EMSCRIPTEN__
        // A service: the engine's own framed TCP listener stands in for a login or lobby server.
        TcpTransport service;
        NetAddress any; any.port = 0;
        CHECK(service.Listen(any, &error));
        const int port = service.LocalAddress().port;
        uint64_t tick = 0;
        std::vector<TransportEvent> events;
        auto pump = [&](int count) { for (int i = 0; i < count; ++i) { service.Poll(++tick, events); e.Step(1); } };
        auto frame = [](uint16_t type, const std::vector<uint8_t>& payload) {
            std::vector<uint8_t> bytes = {static_cast<uint8_t>(type & 0xff), static_cast<uint8_t>(type >> 8)};
            bytes.insert(bytes.end(), payload.begin(), payload.end());
            return bytes;
        };

        CHECK(eval("return link.poll(1) == nil").asBool());
        CHECK(eval("local id, why = link.open{address = 'not an address', port = 80} return id == nil and #why > 0").asBool());
        CHECK(eval("local id, why = link.open{port = 0} return id == nil and #why > 0").asBool());
        CHECK(eval("ID = link.open{address = '127.0.0.1', port = " + std::to_string(port) + "} return ID").asInt() == 1);
        CHECK(eval("return link.poll(ID).state").asString() == "connecting");
        pump(20);
        CHECK(eval("local p = link.poll(ID) return p.state .. #p.messages .. p.error").asString() == "open0");
        PeerId client = 0;
        for (const TransportEvent& event : events) if (event.type == TransportEvent::Type::Connected) client = event.peer;
        CHECK(client != 0);

        // Game -> service: a table travels as binary Json, a string as its bytes, nothing as an empty payload.
        events.clear();
        CHECK(eval("return link.send(ID, 7, {hello = 'world', n = 3}) and link.send(ID, 8, 'raw\\0bytes') and link.send(ID, 65535)").asBool());
        pump(10);
        std::vector<TransportEvent> data;
        for (const TransportEvent& event : events) if (event.type == TransportEvent::Type::Data) data.push_back(event);
        CHECK(data.size() == 3);
        if (data.size() == 3) {
            Json value;
            CHECK(data[0].bytes.size() > 2 && data[0].bytes[0] == 7 && data[0].bytes[1] == 0);
            CHECK(DecodeJson(data[0].bytes.data() + 2, data[0].bytes.size() - 2, value) && value["hello"].asString() == "world" && value["n"].asInt() == 3);
            CHECK(data[1].bytes.size() == 11 && data[1].bytes[0] == 8 && std::string(data[1].bytes.begin() + 2, data[1].bytes.end()) == std::string("raw\0bytes", 9));
            CHECK(data[2].bytes.size() == 2 && data[2].bytes[0] == 0xff && data[2].bytes[1] == 0xff);
        }

        // Service -> game, in order; link.decode turns binary Json back into a value.
        std::vector<uint8_t> encoded;
        Json answer = Json::MakeObject(); answer["ok"] = true; answer["name"] = "Guest0001";
        CHECK(EncodeJson(answer, encoded, 1024));
        std::vector<uint8_t> first = frame(300, encoded), second = frame(9, {'x', 0, 'z'});
        CHECK(service.Send(client, first.data(), first.size()) && service.Send(client, second.data(), second.size()));
        pump(10);
        Json got = eval("local p = link.poll(ID) local v = link.decode(p.messages[1].data) "
                        "return {#p.messages, p.messages[1].type, v.ok, v.name, p.messages[2].type, #p.messages[2].data, link.decode(p.messages[2].data) == nil, #link.poll(ID).messages}");
        CHECK(got[0].asInt() == 2 && got[1].asInt() == 300 && got[2].asBool() && got[3].asString() == "Guest0001");
        CHECK(got[4].asInt() == 9 && got[5].asInt() == 3 && got[6].asBool() && got[7].asInt() == 0);
        CHECK(eval("return link.decode(link.encode({a = {1, 2, 3}})).a[3]").asInt() == 3);

        // The same through commands, for tools and tests.
        Json opened = Call(e, "link.open", ("{\"port\":" + std::to_string(port) + "}").c_str());
        CHECK(opened["ok"].asBool() && opened["result"]["id"].asInt() == 2);
        events.clear(); pump(20);
        PeerId tool = 0;
        for (const TransportEvent& event : events) if (event.type == TransportEvent::Type::Connected) tool = event.peer;
        CHECK(tool != 0 && Call(e, "link.poll", R"({"id":2})")["result"]["state"].asString() == "open");
        events.clear();
        CHECK(Call(e, "link.send", R"({"id":2,"type":5,"hex":"01ff"})")["result"]["bytes"].asInt() == 2);
        CHECK(Call(e, "link.send", R"({"id":2,"type":6,"value":{"a":1}})")["ok"].asBool());
        CHECK(!Call(e, "link.send", R"({"id":2,"type":70000})")["ok"].asBool() && !Call(e, "link.send", R"({"id":2,"type":1,"hex":"0g"})")["ok"].asBool());
        CHECK(!Call(e, "link.send", R"({"id":77,"type":1})")["ok"].asBool());
        pump(10);
        data.clear();
        for (const TransportEvent& event : events) if (event.type == TransportEvent::Type::Data && event.peer == tool) data.push_back(event);
        CHECK(data.size() == 2 && data[0].bytes == std::vector<uint8_t>({5, 0, 1, 0xff}));
        CHECK(service.Send(tool, first.data(), first.size()));
        pump(10);
        Json polled = Call(e, "link.poll", R"({"id":2})")["result"];
        CHECK(polled["messages"].size() == 1 && polled["messages"][0]["type"].asInt() == 300 && polled["messages"][0]["value"]["name"].asString() == "Guest0001");
        CHECK(polled["messages"][0]["size"].asInt() == static_cast<int>(encoded.size()) && polled["messages"][0]["hex"].asString().size() == encoded.size() * 2);
        CHECK(Call(e, "link.state")["result"].size() == 2);

        // Bounds: a payload above 65534 bytes is refused, at most 8 links.
        CHECK(eval("local ok, why = link.send(ID, 1, string.rep('x', 65535)) return ok == false and #why > 0").asBool());
        CHECK(eval("return link.send(ID, 1, string.rep('x', 65534))").asBool());
        CHECK(eval("local n = 0 for i = 1, 8 do if link.open{port = " + std::to_string(port) + "} then n = n + 1 end end return n").asInt() == 6);
        CHECK(Call(e, "link.state")["result"].size() == 8);

        // The service closes a connection: the game sees it, with a reason, and makes room by closing.
        CHECK(service.Disconnect(tool));
        pump(20);
        polled = Call(e, "link.poll", R"({"id":2})")["result"];
        CHECK(polled["state"].asString() == "closed" && !polled["error"].asString().empty());
        CHECK(eval("local ok, why = link.send(2, 1, 'x') return ok == false and #why > 0").asBool());
        CHECK(eval("return link.open{port = " + std::to_string(port) + "}").asInt() == 9);  // took the closed link's slot
        CHECK(eval("return link.close(ID) and not link.close(ID) and link.poll(ID) == nil").asBool());
        CHECK(!Call(e, "link.poll", R"({"id":1})")["ok"].asBool());

        // Nothing listens: the link closes with an error instead of staying "connecting" for ever.
        service.Disconnect(client);
        NetAddress free; free.port = 0;
        int dead = 0;
        { TcpTransport other; CHECK(other.Listen(free, &error)); dead = other.LocalAddress().port; }
        Json refused = Call(e, "link.open", ("{\"port\":" + std::to_string(dead) + "}").c_str());
        CHECK(refused["ok"].asBool());
        pump(400);
        CHECK(Call(e, "link.poll", ("{\"id\":" + std::to_string(refused["result"]["id"].asInt()) + "}").c_str())["result"]["state"].asString() == "closed");

        // Links live as long as the play session's Lua state.
        e.Stop();
        CHECK(Call(e, "link.state")["result"].size() == 0);
#else
        CHECK(eval("local id, why = link.open{port = 7777} return id == nil and #why > 0").asBool());
#endif
        CHECK(e.Scripts().Errors().empty());
    }
    CHECK(PlatformNetSocketsLive() == socketsLive);

    // Lockstep and rollback matches have no links: every peer must compute the same frames.
    {
        const std::string project = SyncProject("links_lockstep", "loopback");
        Engine host, client;
        SyncPrepare(host, client, project, "loopback"); NetworkSteps(host, client, 20);
        Json refused = Call(host, "link.open", R"({"port":7777})");
        CHECK(!refused["ok"].asBool() && refused["error"]["code"].asString() == "link_unavailable");
        host.Stop(); client.Stop(); RemoveAll(project);
    }

    // server/ is the project's back end, never game data.
    CHECK(WriteTextFile(dir + "/server/login/main.cpp", "int main() {}") && WriteTextFile(dir + "/scripts/server_rules.lua", "return {}"));
    bool rules = false;
    for (const std::string& file : GameFiles(dir)) { CHECK(file.rfind("server/", 0) != 0); rules = rules || file == "scripts/server_rules.lua"; }
    CHECK(rules);
    RemoveAll(dir);
}

// Editing a field keeps the Inspector where it was: the whole panel is drawn in the frame of the
// edit (it once drew from data the edit replaced, then flickered and jumped back to the top).
TEST(NativeEditorInspectorKeepsScroll) {
    const std::string project = TempProject("editor_inspector_scroll");
    Engine engine;
    std::string error;
    CHECK(engine.Open(project, &error));
    if (!engine.EnableGpu(nullptr, &error)) { RemoveAll(project); return; }
    CHECK(Call(engine, "entity.create", R"J({"name":"Body","components":{"Transform":{},"MeshRenderer":{"mesh":"cube"},
        "Collider":{},"RigidBody":{}}})J")["ok"].asBool());
    const EntityId body = engine.GetScene().FindByName("Body");
    NativeEditor::Options options;
    options.language = "en";
    {
        NativeEditor editor(engine, nullptr, options);
        CHECK(editor.Init(&error));
        RenderTarget image;
        std::vector<float> scrolls;  // the Inspector scroll after every frame
        auto frames = [&](int count, const std::vector<WindowEvent>& events = std::vector<WindowEvent>()) {
            for (int i = 0; i < count; ++i) {
                editor.Update(i == 0 ? events : std::vector<WindowEvent>(), 1280, 560, 1, Engine::kFixedDt);
                CHECK(editor.DrawToImage(image));
                if (ImGuiWindow* w = ImGui::FindWindowByName("###Inspector")) scrolls.push_back(w->Scroll.y);
            }
        };
        auto click = [&](const std::string& control) {
            const std::array<float, 4> r = editor.InspectorControlRect(control);
            CHECK(r[2] > 0 && r[3] > 0);
            WindowEvent move; move.type = WindowEvent::Type::MouseMove; move.x = r[0] + r[2] * 0.5f; move.y = r[1] + r[3] * 0.5f;
            WindowEvent press = move; press.type = WindowEvent::Type::MouseButton; press.button = 0; press.down = true;
            WindowEvent release = press; release.down = false;
            frames(2, {move}); frames(2, {press}); frames(3, {release});
        };
        frames(3);
        editor.Select(body);
        frames(4);
        ImGuiWindow* inspector = ImGui::FindWindowByName("###Inspector");
        CHECK(inspector && inspector->ScrollMax.y > 0);
        if (!inspector) { RemoveAll(project); return; }
        WindowEvent move; move.type = WindowEvent::Type::MouseMove;
        move.x = inspector->InnerRect.GetCenter().x; move.y = inspector->InnerRect.GetCenter().y;
        WindowEvent wheel; wheel.type = WindowEvent::Type::MouseWheel; wheel.y = -3;
        frames(2, {move}); frames(4, {wheel});
        const float scrolled = inspector->Scroll.y;
        CHECK(scrolled > 0 && scrolled < inspector->ScrollMax.y);  // somewhere in the middle
        auto steady = [&] {
            for (float s : scrolls) CHECK(std::fabs(s - scrolled) < 1.0f);
            scrolls.clear();
        };
        scrolls.clear();
        for (const char* control : {"RigidBody.continuous", "RigidBody.lockRotationY", "Collider.isTrigger", "MeshRenderer.unlit"}) {
            if (editor.InspectorControlRect(control)[2] <= 0) continue;  // scrolled out of view
            click(control);
            std::printf("  %s: %zu frames, scroll %.1f..%.1f (at %.1f)\n", control, scrolls.size(),
                        *std::min_element(scrolls.begin(), scrolls.end()), *std::max_element(scrolls.begin(), scrolls.end()), scrolled);
            steady();
        }
        CHECK(engine.GetScene().Get<RigidBody>(body)->continuous || engine.GetScene().Get<MeshRenderer>(body)->unlit);
    }
    RemoveAll(project);
}

// editor.state / editor.select: agents see what the human sees in the open editor and can point at entities.
// render.pick reports where the surface under a pixel is, not only which entity.
TEST(RenderPickSurfacePoint) {
    Engine e;
    std::string error;
    CHECK(e.Open(TempProject("pick_point"), &error));
    const Json hit = Call(e, "render.pick", R"J({"x":160,"y":90,"width":320,"height":180,"camera":{"eye":[1,10,2.01],"target":[1,0,2]}})J")["result"];
    CHECK(hit["name"].asString() == "Ground");
    CHECK(std::fabs(hit["point"][0].asFloat() - 1) < 0.05f && std::fabs(hit["point"][1].asFloat()) < 0.01f && std::fabs(hit["point"][2].asFloat() - 2) < 0.05f);
    CHECK(hit["normal"][1].asFloat() > 0.99f && std::fabs(hit["distance"].asFloat() - 10) < 0.05f);
    const Json sky = Call(e, "render.pick", R"J({"x":160,"y":10,"width":320,"height":180,"camera":{"eye":[0,1,0],"target":[0,2,-10]}})J")["result"];
    CHECK(sky["id"].asInt() == 0 && !sky.has("point"));
}

TEST(EditorStateForAgents) {
    const std::string project = TempProject("editor_state");
    Engine engine;
    std::string error;
    CHECK(engine.Open(project, &error));
    CHECK(!Call(engine, "editor.state")["result"]["open"].asBool());
    CHECK(Call(engine, "editor.select", R"J({"ids":["Player"]})J")["error"]["code"].asString() == "no_editor");
    if (!engine.EnableGpu(nullptr, &error)) { RemoveAll(project); return; }
    CHECK(Call(engine, "entity.create", R"J({"name":"Far","components":{"Transform":{"position":[40,2,-30]},"MeshRenderer":{"mesh":"cube"}}})J")["ok"].asBool());
    NativeEditor::Options options;
    options.language = "en";
    {
        NativeEditor editor(engine, nullptr, options);
        CHECK(editor.Init(&error));
        RenderTarget image;
        auto frames = [&](int count) {
            for (int i = 0; i < count; ++i) {
                editor.Update({}, 1440, 900, 1, Engine::kFixedDt);
                CHECK(editor.DrawToImage(image));
            }
        };
        frames(3);
        Json state = Call(engine, "editor.state")["result"];
        CHECK(state["open"].asBool() && state["play"].asString() == "editing" && state["selection"].size() == 0);
        CHECK(state["sceneView"]["mode"].asString() == "3D");
        bool sceneVisible = false;
        for (const Json& panel : state["visiblePanels"].items()) sceneVisible = sceneVisible || panel.asString() == "Scene";
        CHECK(sceneVisible);

        // The agent points at an entity: the editor selects it and moves the Scene view there.
        Json selected = Call(engine, "editor.select", R"J({"ids":["Far"],"frame":true})J");
        CHECK(selected["ok"].asBool());
        state = selected["result"];
        CHECK(state["selection"].size() == 1 && state["selection"][0]["name"].asString() == "Far");
        CHECK(editor.Selected() == engine.GetScene().FindByName("Far"));
        const Json& t = state["sceneView"]["target"];
        const Vec3 target(t[0].asFloat(0), t[1].asFloat(0), t[2].asFloat(0));
        CHECK(Length(target - Vec3(40, 2, -30)) < 0.01f);
        CHECK(Call(engine, "editor.select", R"J({"ids":["Nobody"]})J")["error"]["code"].asString() == "entity_not_found");

        // The human's script tab and cursor.
        editor.OpenScript("scripts/player_controller.lua");
        frames(4);
        state = Call(engine, "editor.state")["result"];
        CHECK(state["script"]["path"].asString() == "scripts/player_controller.lua" && state["script"]["line"].asInt() == 1);
        CHECK(state["openScripts"].size() == 1);

        CHECK(Call(engine, "editor.select", R"J({"ids":[]})J")["result"]["selection"].size() == 0);
    }
    CHECK(!Call(engine, "editor.state")["result"]["open"].asBool());  // closed again
    RemoveAll(project);
}

// Ask bubbles: a right click on an object in the Scene view offers the team or an installed CLI; a
// bubble sends what is typed (team.ask / team.send) and shows the conversation.
TEST(NativeEditorAskBubbles) {
    if (!PlatformProcessSupported()) return;
#if defined(_WIN32)
    const std::string project = TempProject("editor_ask");
    const std::string dir = ProcessFixtureDir("editor ask");
    std::string error;
    Backend echo;
    echo.id = "echo";
    echo.displayName = "Fake echo";
    echo.executable = JoinPath(dir, "echo.cmd");
    echo.installHint = "npm install -g fake";
    echo.models = {{"m", "M", true, 0}};
    echo.buildTurn = [](const TurnRequest& request) {
        ProcessOptions options;
        options.executable = request.executable;
        return options;
    };
    echo.parseLine = &ParseClaudeLine;
    CHECK(WriteTextFile(echo.executable, "@echo off\nfindstr \"^\" > \"%~dp0prompt.txt\"\ntype \"%~dp0reply.jsonl\"\n"));
    CHECK(WriteTextFile(JoinPath(dir, "reply.jsonl"), R"J({"type":"result","subtype":"success","is_error":false,"result":"Made it blue.","session_id":"s1"})J" "\n"));
    Engine e;
    CHECK(e.Open(project, &error));
    std::shared_ptr<TeamHandle> team = RegisterTeamCommands(e.Commands(), {echo});
    CHECK(Call(e, "team.add", R"J({"name":"Mina","backend":"echo"})J")["ok"].asBool());
    CHECK(Call(e, "team.settings", R"J({"lead":"mina"})J")["ok"].asBool());
    CHECK(Call(e, "entity.create", R"J({"name":"Target","components":{"Transform":{"position":[3,1,-3],"scale":[1.5,1.5,1.5]},"MeshRenderer":{"mesh":"cube"}}})J")["ok"].asBool());
    const EntityId target = e.GetScene().FindByName("Target");
    if (!e.EnableGpu(nullptr, &error)) { RemoveAll(project); return; }
    NativeEditor::Options options;
    options.language = "en";
    options.onFrame = team->update;
    {
        NativeEditor editor(e, nullptr, options);
        CHECK(editor.Init(&error));
        RenderTarget image;
        auto frames = [&](int count, const std::vector<WindowEvent>& events = std::vector<WindowEvent>()) {
            for (int i = 0; i < count; ++i) {
                editor.Update(i == 0 ? events : std::vector<WindowEvent>(), 1440, 900, 1, Engine::kFixedDt);
                CHECK(editor.DrawToImage(image));
            }
        };
        auto mouse = [&](float x, float y, int button, bool down) {
            WindowEvent event; event.type = WindowEvent::Type::MouseButton; event.x = x; event.y = y; event.button = button; event.down = down;
            frames(2, {event});
        };
        auto type = [&](const std::string& text) {
            std::vector<WindowEvent> events;
            for (unsigned char c : text) { WindowEvent event; event.type = WindowEvent::Type::Text; event.codepoint = c; events.push_back(event); }
            frames(2, events);
            frames(2, {KeyEvent(WindowKey::Enter, true)});
            frames(2, {KeyEvent(WindowKey::Enter, false)});
        };
        frames(3);
        // A right click on the object (framed in the middle of the view) selects it and opens the menu.
        CHECK(Call(e, "editor.select", R"J({"ids":["Target"],"frame":true})J")["ok"].asBool());
        frames(3);
        ImGuiWindow* scene = ImGui::FindWindowByName("###Scene");
        CHECK(scene != nullptr);
        if (!scene) { RemoveAll(project); return; }
        const ImVec2 center = scene->InnerRect.GetCenter();
        WindowEvent move; move.type = WindowEvent::Type::MouseMove; move.x = center.x; move.y = center.y;  // on the gizmo: it only takes the left button
        frames(2, {move});
        mouse(move.x, move.y, 1, true);
        mouse(move.x, move.y, 1, false);
        CHECK(editor.AskMenuEntity() == target && editor.Selected() == target);
        WindowEvent escape = KeyEvent(WindowKey::Escape, true);
        frames(2, {escape});
        frames(2, {KeyEvent(WindowKey::Escape, false)});

        // Ask the installed CLI directly: the conversation is the object's, outside the team chat.
        editor.OpenAskBubble(target, "echo");
        frames(3);
        CHECK(editor.AskBubbleCount() == 1 && editor.AskControlRect(0, "input")[2] > 0);
        type("make it blue");
        const std::string thread = "{\"thread\":\"e" + std::to_string(target) + "-echo\"}";
        Json state;
        for (int i = 0; i < 300; ++i) {
            frames(1);
            state = Call(e, "team.thread", thread.c_str())["result"];
            if (state["messages"].size() >= 2 && !state["running"].asBool()) break;
            PlatformSleep(0.02);
        }
        CHECK(state["messages"].size() == 2 && state["messages"][1]["text"].asString() == "Made it blue.");
        std::string prompt;
        CHECK(ReadTextFile(JoinPath(dir, "prompt.txt"), prompt) && prompt.find("\"Target\"") != std::string::npos && prompt.find("make it blue") != std::string::npos);
        CHECK(Call(e, "team.messages")["result"]["messages"].size() == 0);

        // A spot on the ground: the menu knows the point on its surface, and an agent is told where it is.
        const ImVec2 ground(scene->InnerRect.Min.x + 60, scene->InnerRect.Max.y - 40);
        move.x = ground.x; move.y = ground.y;
        frames(2, {move});
        mouse(ground.x, ground.y, 1, true);
        mouse(ground.x, ground.y, 1, false);
        const EntityId groundId = e.GetScene().FindByName("Ground");
        CHECK(editor.AskMenuEntity() == groundId && std::fabs(editor.AskMenuPoint().y) < 0.01f);
        CHECK(editor.Selected() == target);  // a right click alone does not change the selection
        const Vec3 spot = editor.AskMenuPoint();
        frames(2, {KeyEvent(WindowKey::Escape, true)});
        frames(2, {KeyEvent(WindowKey::Escape, false)});
        editor.OpenAskSpot(spot, groundId, "echo");
        frames(3);
        CHECK(editor.AskBubbleCount() == 2);
        type("put a tree here");
        for (int i = 0; i < 300; ++i) {
            frames(1);
            const Json threads = Call(e, "team.threads")["result"];
            bool done = threads.size() == 2;
            for (const Json& t : threads.items()) done = done && !t["running"].asBool() && t["messages"].asInt() == 2;
            if (done) break;
            PlatformSleep(0.02);
        }
        CHECK(ReadTextFile(JoinPath(dir, "prompt.txt"), prompt) && prompt.find("world position") != std::string::npos &&
              prompt.find("\"Ground\"") != std::string::npos && prompt.find("put a tree here") != std::string::npos);
        bool spotThread = false;
        const Json threads = Call(e, "team.threads")["result"];
        for (const Json& t : threads.items()) spotThread = spotThread || t["thread"].asString().rfind("p", 0) == 0;
        CHECK(spotThread);

        // Ask the team: the message goes to the team chat, naming the object.
        editor.OpenAskBubble(target, "");
        frames(3);
        CHECK(editor.AskBubbleCount() == 3);
        type("what is this?");
        const Json messages = Call(e, "team.messages")["result"]["messages"];
        CHECK(messages.size() >= 1 && messages[0]["text"].asString() == "[Target #" + std::to_string(target) + "] what is this?");
        // The Agent Chat panel: a conversation with the CLI that is not about one object.
        editor.FocusAgentChat();
        frames(4);
        CHECK(editor.AgentChatInputRect()[2] > 0);
        type("add a sound");
        // @ completes a scene object in a direct conversation: "@Targ" + Tab becomes "@Target ".
        {
            std::vector<WindowEvent> events;
            for (unsigned char c : std::string("@Targ")) { WindowEvent event; event.type = WindowEvent::Type::Text; event.codepoint = c; events.push_back(event); }
            frames(3, events);
            frames(2, {KeyEvent(WindowKey::Tab, true)});
            frames(2, {KeyEvent(WindowKey::Tab, false)});
        }
        Json chatState;
        for (int i = 0; i < 300; ++i) {
            frames(1);
            chatState = Call(e, "team.thread", R"J({"thread":"chat-echo"})J")["result"];
            if (chatState["messages"].size() >= 2 && !chatState["running"].asBool()) break;
            PlatformSleep(0.02);
        }
        CHECK(chatState["messages"].size() == 2 && chatState["messages"][0]["text"].asString() == "add a sound");
        frames(30);  // the panel reads the finished turn (it polls a few times a second)
        frames(2, {KeyEvent(WindowKey::Enter, true)});
        frames(2, {KeyEvent(WindowKey::Enter, false)});
        for (int i = 0; i < 300; ++i) {
            frames(1);
            chatState = Call(e, "team.thread", R"J({"thread":"chat-echo"})J")["result"];
            if (chatState["messages"].size() >= 4 && !chatState["running"].asBool()) break;
            PlatformSleep(0.02);
        }
        CHECK(chatState["messages"].size() >= 3 && chatState["messages"][2]["text"].asString() == "@Target");
        CHECK(ReadTextFile(JoinPath(dir, "prompt.txt"), prompt) && prompt.find("Agent Chat panel") != std::string::npos);

        // Files dropped on the Agent Chat panel or on a bubble go with that input's next message; one
        // from outside the project is copied into it and named in the prompt.
        const std::string note = JoinPath(dir, "note.txt");
        CHECK(WriteTextFile(note, "notes"));
        const std::array<float, 4> chatInput = editor.AgentChatInputRect();
        WindowEvent drop;
        drop.type = WindowEvent::Type::DropFile;
        drop.path = note;
        drop.x = chatInput[0] + chatInput[2] * 0.5f;
        drop.y = chatInput[1] + chatInput[3] * 0.5f;
        frames(3, {drop});
        CHECK(editor.AgentChatAttachments() == std::vector<std::string>{note});
        const std::array<float, 4> bubbleInput = editor.AskControlRect(0, "input");
        drop.x = bubbleInput[0] + bubbleInput[2] * 0.5f;
        drop.y = bubbleInput[1] + bubbleInput[3] * 0.5f;
        frames(3, {drop});
        CHECK(editor.AskAttachments(0) == std::vector<std::string>{note} && editor.AgentChatAttachments().size() == 1);
        frames(30);
        editor.FocusAgentChat();
        frames(3);
        type("read this");
        for (int i = 0; i < 300; ++i) {
            frames(1);
            chatState = Call(e, "team.thread", R"J({"thread":"chat-echo"})J")["result"];
            if (chatState["messages"].size() >= 6 && !chatState["running"].asBool()) break;
            PlatformSleep(0.02);
        }
        const Json withFile = chatState["messages"][4];
        CHECK(withFile["text"].asString() == "read this" && withFile["attachments"].size() == 1 && editor.AgentChatAttachments().empty());
        const std::string copied = withFile["attachments"][0]["path"].asString();
        CHECK(copied.rfind(".oe/team/attachments/", 0) == 0 && FileExists(JoinPath(project, copied)));
        CHECK(ReadTextFile(JoinPath(dir, "prompt.txt"), prompt) && prompt.find("Attached file: " + copied) != std::string::npos);

        // Deleting the object closes its bubbles; the spot's stays.
        CHECK(Call(e, "entity.delete", R"J({"id":"Target"})J")["ok"].asBool());
        frames(2);
        CHECK(editor.AskBubbleCount() == 1);
    }
    team.reset();
    RemoveAll(project);
#endif
}

// ----- navigation mesh -------------------------------------------------------------

// A 20 x 20 m floor cut by a wall that leaves a gap at +X, a ramp and a pillar.
void NavScene(Engine& e) {
    Call(e, "scene.new", R"J({"empty":true})J");
    Call(e, "entity.create", R"J({"name":"Floor","components":{"Transform":{"position":[0,-0.5,0],"scale":[20,1,20]},"MeshRenderer":{},"Collider":{}}})J");
    Call(e, "entity.create", R"J({"name":"Wall","components":{"Transform":{"position":[-2,1,0],"scale":[14,2,0.5]},"MeshRenderer":{},"Collider":{}}})J");
    Call(e, "entity.create", R"J({"name":"Ramp","components":{"Transform":{"position":[6,0.6,-5],"rotation":[0,0,20],"scale":[6,0.2,3]},"MeshRenderer":{},"Collider":{}}})J");
    Call(e, "entity.create", R"J({"name":"Pillar","components":{"Transform":{"position":[4,1,5]},"Collider":{"shape":"capsule","radius":0.6,"height":2}}})J");
}

TEST(NavMeshBakeAndQueries) {
    Engine e;
    std::string err;
    CHECK(e.Open(TempProject("navmesh"), &err));
    auto vec = [](const Json& v) { return Vec3(v[0].asFloat(), v[1].asFloat(), v[2].asFloat()); };

    // Nothing to stand on: the state says so, queries are errors with a hint.
    Call(e, "scene.new", R"J({"empty":true})J");
    Json state = Call(e, "nav.state")["result"];
    CHECK(!state["baked"].asBool() && state.has("error") && state.has("hint"));
    Json none = Call(e, "nav.path", R"J({"from":[0,0,0],"to":[1,0,0]})J");
    CHECK(!none["ok"].asBool() && none["error"]["code"].asString() == "no_navmesh" && !none["error"]["hint"].asString().empty());

    NavScene(e);
    state = Call(e, "nav.state")["result"];
    CHECK(state["baked"].asBool() && state["colliders"].asInt() == 4 && state["meshes"].asInt() == 0);
    CHECK(state["polygons"].asInt() > 4 && state["settings"]["agentRadius"].asFloat() == 0.4f);
    // The floor less the agent's radius along its rim, the wall and the pillar.
    CHECK(state["area"].asFloat() > 300.0f && state["area"].asFloat() < 369.0f);
    CHECK(std::fabs(state["boundsMin"][0].asFloat() + 9.6f) < 0.25f && std::fabs(state["boundsMin"][1].asFloat()) < 0.06f);

    // Around the end of the wall (x = 5) instead of the 16 m straight through it.
    Json path = Call(e, "nav.path", R"J({"from":[-8,0,-8],"to":[-8,0,8]})J")["result"];
    CHECK(path["found"].asBool() && !path["partial"].asBool() && path["points"].size() >= 3);
    CHECK(path["length"].asFloat() > 28.0f && path["length"].asFloat() < 36.0f);
    bool around = false;
    float walked = 0.0f;
    for (size_t i = 0; i < path["points"].size(); ++i) {
        const Vec3 at = vec(path["points"][i]);
        around = around || at.x > 5.2f;
        CHECK(std::fabs(at.y) < 0.06f);  // on the floor's top
        if (i) walked += Length(at - vec(path["points"][i - 1]));
    }
    CHECK(around && std::fabs(walked - path["length"].asFloat()) < 1e-3f);
    CHECK(Near(vec(path["points"][0]), Vec3(-8, 0, -8), 0.06f) && Near(vec(path["points"][path["points"].size() - 1]), Vec3(-8, 0, 8), 0.06f));
    CHECK(Call(e, "nav.path", R"J({"from":[-8,0,-8],"to":[-8,0,8]})J")["result"] == path);  // the same question, the same answer

    // The walk stops at the wall (its face at z = -0.25, less the radius); along it nothing is in the way.
    Json ray = Call(e, "nav.raycast", R"J({"from":[-5,0,-5],"to":[-5,0,5]})J")["result"];
    CHECK(ray["onMesh"].asBool() && ray["hit"].asBool() && std::fabs(vec(ray["point"]).z + 0.7f) < 0.25f && vec(ray["normal"]).z < -0.9f);
    ray = Call(e, "nav.raycast", R"J({"from":[-5,0,-5],"to":[2,0,-5]})J")["result"];
    CHECK(!ray["hit"].asBool() && std::fabs(ray["distance"].asFloat() - 7.0f) < 0.01f);
    CHECK(!Call(e, "nav.raycast", R"J({"from":[50,0,50],"to":[0,0,0]})J")["result"]["onMesh"].asBool());

    // Above the wall the nearest ground is beside it; out of range there is none.
    Json nearest = Call(e, "nav.nearest", R"J({"point":[0,3,0],"range":5})J")["result"];
    CHECK(nearest["found"].asBool() && std::fabs(std::fabs(vec(nearest["point"]).z) - 0.7f) < 0.25f);
    CHECK(!Call(e, "nav.nearest", R"J({"point":[0,3,0],"range":0.5})J")["result"]["found"].asBool());
    CHECK(!Call(e, "nav.nearest", R"J({"point":[0,0,0],"range":-1})J")["ok"].asBool());
    Json far = Call(e, "nav.path", R"J({"from":[-8,0,-8],"to":[80,0,0]})J")["result"];
    CHECK(!far["found"].asBool() && far["reason"].asString().rfind("to ", 0) == 0);

    // The overlay is part of the picture.
    const std::string plain = Call(e, "render.screenshot", R"J({"width":160,"height":120,"camera":{"eye":[0,24,14],"target":[0,0,0]}})J")["result"]["hash"].asString();
    CHECK(Call(e, "render.screenshot", R"J({"width":160,"height":120,"navmesh":true,"camera":{"eye":[0,24,14],"target":[0,0,0]}})J")["result"]["hash"].asString() != plain);

    // Edits while stopped are followed. Things that move, triggers and ignored entities are not ground.
    Call(e, "entity.create", R"J({"name":"Crate","components":{"Transform":{"position":[-8,0.5,-4]},"Collider":{},"RigidBody":{}}})J");
    Call(e, "entity.create", R"J({"name":"Zone","components":{"Transform":{"position":[-8,0.5,4]},"Collider":{"isTrigger":true}}})J");
    Call(e, "entity.create", R"J({"name":"Hero","components":{"Transform":{"position":[0,1,-6]},"CharacterBody":{}}})J");
    state = Call(e, "nav.state")["result"];
    CHECK(state["colliders"].asInt() == 4);
    CHECK(Call(e, "nav.path", R"J({"from":[-8,0,-8],"to":[-8,0,8]})J")["result"] == path);
    Call(e, "component.add", R"J({"id":"Wall","type":"NavModifier"})J");
    Json open = Call(e, "nav.path", R"J({"from":[-8,0,-8],"to":[-8,0,8]})J")["result"];
    CHECK(Call(e, "nav.state")["result"]["colliders"].asInt() == 3 && std::fabs(open["length"].asFloat() - 16.0f) < 0.05f && open["points"].size() == 2);
    // Unwalkable: still in the way, and nobody stands on it.
    Call(e, "component.set", R"J({"id":"Wall","type":"NavModifier","values":{"mode":"unwalkable"}})J");
    CHECK(Call(e, "nav.path", R"J({"from":[-8,0,-8],"to":[-8,0,8]})J")["result"] == path);
    const float withRamp = Call(e, "nav.state")["result"]["area"].asFloat();
    Call(e, "component.add", R"J({"id":"Ramp","type":"NavModifier","values":{"mode":"unwalkable"}})J");
    CHECK(Call(e, "nav.state")["result"]["area"].asFloat() < withRamp - 5.0f);
    Call(e, "component.remove", R"J({"id":"Ramp","type":"NavModifier"})J");
    Call(e, "component.remove", R"J({"id":"Wall","type":"NavModifier"})J");

    // A second floor nobody can get to: the path goes as near as the mesh allows.
    Call(e, "entity.create", R"J({"name":"Island","components":{"Transform":{"position":[30,-0.5,0],"scale":[6,1,6]},"MeshRenderer":{},"Collider":{}}})J");
    Json partial = Call(e, "nav.path", R"J({"from":[-8,0,-8],"to":[30,0,0]})J")["result"];
    CHECK(partial["found"].asBool() && partial["partial"].asBool());
    CHECK(vec(partial["points"][partial["points"].size() - 1]).x < 10.0f);

    // Settings: a wider agent leaves less floor; models as the source; only what is below the NavMesh entity.
    const float before = Call(e, "nav.state")["result"]["area"].asFloat();
    Call(e, "entity.create", R"J({"name":"Nav","components":{"NavMesh":{"agentRadius":1.0}}})J");
    state = Call(e, "nav.state")["result"];
    CHECK(state["area"].asFloat() < before - 20.0f && state["settings"]["agentRadius"].asFloat() == 1.0f);
    Call(e, "component.set", R"J({"id":"Nav","type":"NavMesh","values":{"agentRadius":0.4,"source":"meshes"}})J");
    state = Call(e, "nav.state")["result"];
    CHECK(state["baked"].asBool() && state["colliders"].asInt() == 0 && state["meshes"].asInt() == 4);  // the pillar has no mesh
    CHECK(Call(e, "nav.path", R"J({"from":[-8,0,-8],"to":[-8,0,8]})J")["result"]["length"].asFloat() > 28.0f);
    Call(e, "component.set", R"J({"id":"Nav","type":"NavMesh","values":{"source":"all","collect":"children"}})J");
    CHECK(!Call(e, "nav.state")["result"]["baked"].asBool());
    Call(e, "entity.set_parent", R"J({"id":"Island","parent":"Nav"})J");
    state = Call(e, "nav.state")["result"];
    CHECK(state["baked"].asBool() && state["colliders"].asInt() == 1 && state["meshes"].asInt() == 1 && state["area"].asFloat() < 30.0f);
    Call(e, "entity.delete", R"J({"id":"Nav"})J");

    // Playing, the mesh stays as baked until the game asks: the wall goes, nav.bake() opens the way.
    Json eval = Json::MakeObject();
    eval["code"] = "local a, b = {x=-8,y=0,z=-8}, {x=-8,y=0,z=8}\n"
                   "local first = #nav.path(a, b)\n"
                   "scene.destroy(scene.find('Wall'))\n"
                   "local stale = #nav.path(a, b)\n"
                   "local baked = nav.bake()\n"
                   "local path, partial = nav.path(a, b)\n"
                   "local hit = nav.raycast({x=-5,y=0,z=-5}, {x=-5,y=0,z=30})\n"
                   "return {first, stale, baked, #path, partial, nav.nearest({x=0,y=3,z=0}, 5).y, nav.nearest({x=90,y=0,z=0}) == nil, nav.path(a, {x=90,y=0,z=0}) == nil, hit.point.z}";
    Call(e, "sim.step", R"J({"frames":1})J");
    Json lua = e.Call("script.eval", eval);
    CHECK(lua["ok"].asBool());
    const Json& got = lua["result"]["value"];
    CHECK(got[0].asInt() >= 3 && got[1].asInt() == got[0].asInt() && got[2].asBool() && got[3].asInt() == 2 && !got[4].asBool());
    CHECK(std::fabs(got[5].asFloat()) < 0.06f && got[6].asBool() && got[7].asBool() && std::fabs(got[8].asFloat() - 9.6f) < 0.25f);
    Call(e, "sim.stop");
    CHECK(Call(e, "nav.path", R"J({"from":[-8,0,-8],"to":[-8,0,8]})J")["result"]["length"].asFloat() > 28.0f);  // the wall is back
}

TEST(NavAgentWalksPath) {
    Engine e;
    std::string err;
    const std::string project = TempProject("nav_agent");
    CHECK(e.Open(project, &err));
    NavScene(e);
    CHECK(WriteTextFile(JoinPath(project, "scripts/walker.lua"),
                        "local navigation = require('oe.nav')\n"
                        "local Walker = {}\n"
                        "function Walker:onStart()\n"
                        "  self.agent = navigation.agent(self.id, {speed = 4})\n"
                        "  game.set(scene.name(self.id) .. ':found', self.agent:moveTo({x = -8, y = 0, z = 8}))\n"
                        "  game.set(scene.name(self.id) .. ':left', self.agent:remaining())\n"
                        "end\n"
                        "function Walker:onUpdate(dt)\n"
                        "  game.set(scene.name(self.id) .. ':moving', self.agent:update(dt))\n"
                        "end\n"
                        "return Walker\n"));
    // One moved by its Transform (it keeps its height above the mesh), one by physics.
    Call(e, "entity.create", R"J({"name":"Ghost","components":{"Transform":{"position":[-8,1,-8]},"Script":{"path":"scripts/walker.lua"}}})J");
    Call(e, "entity.create", R"J({"name":"Body","components":{"Transform":{"position":[-6,0.9,-8]},"CharacterBody":{},"Script":{"path":"scripts/walker.lua"}}})J");
    Call(e, "sim.step", R"J({"frames":120})J");
    Json values = Call(e, "game.state")["result"]["data"];
    CHECK(values["Ghost:found"].asBool() && values["Body:found"].asBool() && values["Ghost:moving"].asBool());
    CHECK(values["Ghost:left"].asFloat() > 28.0f && values["Ghost:left"].asFloat() < 36.0f);
    Vec3 ghost = PosOf(e, "Ghost"), body = PosOf(e, "Body");
    CHECK(Length(ghost - Vec3(-8, 1, -8)) > 7.0f && Length(ghost - Vec3(-8, 1, -8)) < 8.2f && std::fabs(ghost.y - 1.0f) < 0.06f);  // 2 s at 4 m/s
    CHECK(body.x > -4.0f && body.z > -8.5f);
    Call(e, "sim.step", R"J({"frames":480})J");
    values = Call(e, "game.state")["result"]["data"];
    ghost = PosOf(e, "Ghost");
    body = PosOf(e, "Body");
    CHECK(!values["Ghost:moving"].asBool() && !values["Body:moving"].asBool());
    CHECK(std::fabs(ghost.x + 8.0f) < 0.15f && std::fabs(ghost.z - 8.0f) < 0.15f && std::fabs(ghost.y - 1.0f) < 0.06f);
    CHECK(std::fabs(body.x + 8.0f) < 0.3f && std::fabs(body.z - 8.0f) < 0.3f && body.y > 0.8f && body.y < 1.0f);
    // It turned to face where it was going last: from the gap back toward -X, +Z (yaw 90 looks along -X).
    const Json rotation = Call(e, "entity.get", R"J({"id":"Ghost"})J")["result"]["components"]["Transform"]["rotation"];
    CHECK(std::fabs(rotation[1].asFloat() - 116.0f) < 6.0f);
}

int main() {
    Log::SetEcho(false);
    std::setvbuf(stdout, nullptr, _IONBF, 0);
    // OE_TEST_FILTER=Name runs only the tests whose names contain it (repeat a flaky one, iterate on one).
    const char* filter = std::getenv("OE_TEST_FILTER");
    size_t ran = 0;
    for (const TestCase& t : Tests()) {
        if (filter && *filter && !std::strstr(t.name, filter)) continue;
        int before = g_failures;
        t.fn();
        ++ran;
        std::printf("%s %s\n", g_failures == before ? "PASS" : "FAIL", t.name);
    }
    std::printf("\n%zu tests, %d failed checks\n", ran, g_failures);
    return g_failures == 0 ? 0 : 1;
}
